// When a new condition is added to an active session, these demographic
// fields are auto-filled from whatever's already been entered for another
// active condition, so the clinician isn't re-typing side/occupation/sport
// for every coexisting diagnosis on the same patient.
const SHARED_FIELD_KEYS = ["side", "occupation", "sport", "competitionLevel"];

// "Dominant arm" (Shoulder/Elbow templates) and "Dominant hand" (Wrist/Hand
// templates) are the same clinical fact under a region-appropriate label and
// a different field key \u2014 aliased here so either one auto-fills the other.
const DOMINANT_SIDE_ALIASES = ["dominantArm", "dominantHand"];

function findConditionById(id) {
  for (const region of Object.values(REGIONS)) {
    const found = getRegionConditions(region).find((c) => c.id === id);
    if (found) return found;
  }
  return null;
}

function deriveSharedDefaults(session) {
  const defaults = {};
  for (const key of SHARED_FIELD_KEYS) {
    for (const cid of session.order) {
      const s = session.statesByConditionId[cid];
      if (s && s[key] != null && s[key] !== "") {
        defaults[key] = s[key];
        break;
      }
    }
  }
  outer: for (const cid of session.order) {
    const s = session.statesByConditionId[cid];
    if (!s) continue;
    for (const key of DOMINANT_SIDE_ALIASES) {
      if (s[key] != null && s[key] !== "") {
        for (const aliasKey of DOMINANT_SIDE_ALIASES) defaults[aliasKey] = s[key];
        break outer;
      }
    }
  }
  return defaults;
}

function addConditionToSession(session, condition) {
  if (session.statesByConditionId[condition.id]) return session; // already active
  return {
    order: [...session.order, condition.id],
    statesByConditionId: { ...session.statesByConditionId, [condition.id]: deriveSharedDefaults(session) },
  };
}

/* ============================================================================
   GENERIC / SHARED UI COMPONENTS
============================================================================ */
function ProgressDot({ done }) {
  return done ? <CheckCircle2 size={18} color={T.teal} /> : <Circle size={18} color={T.borderStrong} />;
}

function CollapsibleSection({ index, title, subtitle, isOpen, onToggle, hasContent, children, nextTitle, onNext }) {
  return (
    <div className="rounded-2xl mb-3 overflow-hidden" style={{ border: `1px solid ${T.border}`, background: T.surface }}>
      <button onClick={onToggle} className="w-full flex items-center gap-3 px-4 py-4 text-left active:opacity-70" style={{ minHeight: 56 }}>
        <span className="flex items-center justify-center rounded-full text-sm font-semibold shrink-0" style={{ width: 28, height: 28, background: T.tealTint, color: T.tealDark }}>
          {index}
        </span>
        <span className="flex-1 min-w-0">
          <div className="font-semibold text-[15px]" style={{ color: T.ink }}>{title}</div>
          {subtitle && <div className="text-[13px] truncate" style={{ color: T.inkSoft }}>{subtitle}</div>}
        </span>
        <ProgressDot done={hasContent} />
        {isOpen ? <ChevronDown size={20} color={T.inkSoft} /> : <ChevronRight size={20} color={T.inkSoft} />}
      </button>
      {isOpen && (
        <div className="px-4 pb-5 pt-1" style={{ borderTop: `1px solid ${T.border}` }}>
          {children}
          {onNext && nextTitle && (
            <button
              onClick={onNext}
              className="w-full mt-5 rounded-xl px-4 py-3 font-semibold text-[14px] flex items-center justify-center gap-1.5 active:scale-95 transition"
              style={{ background: T.tealTint, color: T.tealDark, border: `1px solid ${T.teal}`, minHeight: 48 }}
            >
              Next: {nextTitle} <ChevronRight size={17} />
            </button>
          )}
        </div>
      )}
    </div>
  );
}

function SubLabel({ children }) {
  if (!children) return null;
  return <div className="text-[12px] font-semibold uppercase tracking-wide mb-2 mt-4 first:mt-0" style={{ color: T.inkSoft }}>{children}</div>;
}

// An option like "None", "None noted", or "Normal" asserts the absence of
// findings, so it can't logically coexist with a positive finding in the
// same field - a note reading "previous treatment included none and
// analgesics" is contradictory and would be a real documentation defect in
// a medical record. Selecting an exclusive option therefore clears the
// positive findings, and selecting a positive finding clears the exclusive
// option. Handled here in the shared component so every checkbox field in
// the app gets it without needing per-field wiring.
const EXCLUSIVE_OPTION_RE = /^(none|none noted|none palpable|none identified|normal|no deformity|not applicable|n\/a)$/i;

function CheckboxGroup({ options, selected, onChange }) {
  const toggle = (opt) => {
    const isExclusive = EXCLUSIVE_OPTION_RE.test(opt);
    if (selected.includes(opt)) {
      onChange(selected.filter((s) => s !== opt));
      return;
    }
    if (isExclusive) {
      // Selecting "None"/"Normal" replaces any positive findings.
      onChange([opt]);
      return;
    }
    // Selecting a positive finding drops any exclusive option.
    onChange([...selected.filter((s) => !EXCLUSIVE_OPTION_RE.test(s)), opt]);
  };
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((opt) => {
        const active = selected.includes(opt);
        return (
          <button key={opt} onClick={() => toggle(opt)} className="rounded-full px-3 py-2 text-[14px] font-medium flex items-center gap-1.5 active:scale-95 transition" style={{ minHeight: 40, background: active ? T.tealDark : T.slateChip, color: active ? "#fff" : T.ink, border: `1px solid ${active ? T.tealDark : T.border}` }}>
            {active && <Check size={14} />}
            {opt}
          </button>
        );
      })}
    </div>
  );
}

// For special/provocative tests: each test can be marked Positive or
// Negative (not just "selected"), since the clinically meaningful thing
// about a special test isn't that it was performed but what it showed.
// values is a map of { [testName]: "positive" | "negative" }; a test with
// no entry is simply not yet marked. Tapping the active state again clears
// it back to unmarked.
function TestGrid({ tests, values, onChange }) {
  return (
    <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${T.border}` }}>
      {tests.map((t, i) => {
        const val = values[t];
        return (
          <div key={t} className="flex items-center justify-between gap-2 px-3 py-2.5" style={{ borderTop: i ? `1px solid ${T.border}` : "none" }}>
            <span className="text-[14px] flex-1" style={{ color: T.ink }}>{t}</span>
            <div className="flex gap-1.5 shrink-0">
              <button
                onClick={() => onChange(t, val === "positive" ? null : "positive")}
                className="rounded-lg px-3 py-1.5 text-[12.5px] font-semibold active:scale-95 transition"
                style={{ minHeight: 32, background: val === "positive" ? T.amber : T.slateChip, color: val === "positive" ? "#fff" : T.inkSoft, border: `1px solid ${val === "positive" ? T.amber : T.border}` }}
              >
                Positive
              </button>
              <button
                onClick={() => onChange(t, val === "negative" ? null : "negative")}
                className="rounded-lg px-3 py-1.5 text-[12.5px] font-semibold active:scale-95 transition"
                style={{ minHeight: 32, background: val === "negative" ? T.green : T.slateChip, color: val === "negative" ? "#fff" : T.inkSoft, border: `1px solid ${val === "negative" ? T.green : T.border}` }}
              >
                Negative
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function ButtonSelect({ options, value, onChange, columns }) {
  return (
    <div className="grid gap-2" style={{ gridTemplateColumns: `repeat(${columns || Math.min(options.length, 4)}, minmax(0,1fr))` }}>
      {options.map((opt) => {
        const active = value === opt;
        return (
          <button key={opt} onClick={() => onChange(active ? null : opt)} className="rounded-xl px-2 py-2.5 text-[14px] font-medium active:scale-95 transition" style={{ minHeight: 44, background: active ? T.teal : T.slateChip, color: active ? "#fff" : T.ink, border: `1px solid ${active ? T.teal : T.border}` }}>
            {opt}
          </button>
        );
      })}
    </div>
  );
}

function VASSlider({ value, onChange }) {
  const v = value ?? 0;
  const color = v >= 7 ? T.red : v >= 4 ? T.amber : T.green;
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <span className="text-[13px]" style={{ color: T.inkSoft }}>VAS pain score</span>
        <span className="text-[20px] font-bold" style={{ color }}>
          {v}<span className="text-[13px] font-normal" style={{ color: T.inkSoft }}>/10</span>
        </span>
      </div>
      <input type="range" min={0} max={10} step={1} value={v} onChange={(e) => onChange(Number(e.target.value))} className="w-full" style={{ accentColor: color, height: 36 }} />
      <div className="flex justify-between text-[11px] mt-0.5" style={{ color: T.inkSoft }}>
        <span>No pain</span><span>Worst pain</span>
      </div>
    </div>
  );
}

function NumberField({ label, value, onChange, suffix, placeholder }) {
  return (
    <div className="flex items-center justify-between gap-3 py-1.5">
      <span className="text-[14px]" style={{ color: T.ink }}>{label}</span>
      <div className="flex items-center gap-1">
        <input inputMode="numeric" type="number" placeholder={placeholder || "0"} value={value ?? ""} onChange={(e) => onChange(e.target.value === "" ? null : Number(e.target.value))} className="text-right rounded-lg px-2 py-2 text-[15px] font-medium" style={{ width: 68, border: `1px solid ${T.border}`, background: T.slateChip, color: T.ink }} />
        {suffix && <span className="text-[13px]" style={{ color: T.inkSoft }}>{suffix}</span>}
      </div>
    </div>
  );
}

function TextField({ label, value, onChange, placeholder }) {
  return (
    <div className="mb-3">
      <div className="text-[13px] mb-1" style={{ color: T.inkSoft }}>{label}</div>
      <input type="text" value={value || ""} placeholder={placeholder} onChange={(e) => onChange(e.target.value)} className="w-full rounded-lg px-3 py-2.5 text-[15px]" style={{ border: `1px solid ${T.border}`, background: T.slateChip, color: T.ink }} />
    </div>
  );
}

/* Native date picker — for acute/trauma templates recording an injury or
   event date, a bounded value rather than a free-text duration. */
function DateField({ label, value, onChange }) {
  return (
    <div className="mb-3">
      <div className="text-[13px] mb-1" style={{ color: T.inkSoft }}>{label}</div>
      <input type="date" value={value || ""} onChange={(e) => onChange(e.target.value)} className="w-full rounded-lg px-3 py-2.5 text-[15px]" style={{ border: `1px solid ${T.border}`, background: T.slateChip, color: T.ink, minHeight: 44 }} />
    </div>
  );
}

// Reference aid only — standard/approximate normal active ROM ranges shown
// alongside each motion's input so the clinician can see them while
// entering values. Purely informational: never used for validation, never
// changes what's stored in state. Keyed by region first, then by the exact
// motion label used in that region's condition data, since the same motion
// name (e.g. "Flexion") means a different joint — and a different normal
// range — depending on which region's template it appears in (elbow flexion
// ~150° vs wrist flexion ~80°). Hand & Wrist Trauma templates live under the
// "hand" region but mostly measure wrist/forearm motion using the same
// names as the Wrist region, so that bucket mirrors wrist values plus a few
// genuinely hand/thumb-specific motions. Ranges marked "approx." are less
// tightly standardized across sources than the others; if a motion name
// isn't listed for its region (e.g. grip strength, two-point
// discrimination, thumb opposition), no reference is shown rather than
// guessing.
const ROM_REFERENCE = {
  shoulder: {
    "Forward Flexion": "0\u2013180\u00b0",
    Abduction: "0\u2013180\u00b0",
    "External Rotation": "0\u201390\u00b0",
    "Internal Rotation": "0\u201370\u00b0 (approx.; commonly reported relative to spinal level rather than degrees)",
  },
  elbow: {
    Flexion: "0\u2013150\u00b0",
    Extension: "0\u00b0 (up to ~10\u00b0 hyperextension may be normal)",
    Pronation: "0\u201380\u00b0",
    Supination: "0\u201380\u00b0",
  },
  wrist: {
    Flexion: "0\u201380\u00b0 (approx.)",
    Extension: "0\u201370\u00b0 (approx.)",
    Pronation: "0\u201380\u00b0",
    Supination: "0\u201380\u00b0",
    "Radial deviation": "0\u201320\u00b0",
    "Ulnar deviation": "0\u201330\u00b0",
  },
  hand: {
    Flexion: "0\u201380\u00b0 (approx.; wrist flexion)",
    Extension: "0\u201370\u00b0 (approx.; wrist extension)",
    Pronation: "0\u201380\u00b0",
    Supination: "0\u201380\u00b0",
    "Radial deviation": "0\u201320\u00b0",
    "Ulnar deviation": "0\u201330\u00b0",
    "MCP flexion": "0\u201390\u00b0 (approx.; MCP joint)",
    "Palmar abduction": "0\u201370\u00b0 (approx.; thumb)",
    "Radial abduction": "0\u201360\u00b0 (approx.; thumb)",
  },
  peripheralNerve: {},
};

function ROMTable({ motions, values, onChange, region }) {
  const refs = ROM_REFERENCE[region] || {};
  return (
    <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${T.border}` }}>
      <div className="grid text-[12px] font-semibold uppercase tracking-wide px-3 py-2" style={{ gridTemplateColumns: "1.4fr 1fr 1fr", background: T.tealTint, color: T.tealDark }}>
        <span>Motion</span><span className="text-center">Active °</span><span className="text-center">Passive °</span>
      </div>
      {motions.map((m, i) => {
        const row = values[m] || {};
        const ref = refs[m];
        return (
          <div key={m} className="px-3 py-2" style={{ background: i % 2 ? T.surface : "#FAFCFC", borderTop: `1px solid ${T.border}` }}>
            <div className="grid items-center" style={{ gridTemplateColumns: "1.4fr 1fr 1fr" }}>
              <span className="text-[13px]" style={{ color: T.ink }}>{m}</span>
              <input type="number" inputMode="numeric" value={row.active ?? ""} onChange={(e) => onChange(m, { ...row, active: e.target.value === "" ? null : Number(e.target.value) })} className="mx-auto text-center rounded-lg px-1 py-1.5 text-[14px]" style={{ width: 56, border: `1px solid ${T.border}` }} />
              <input type="number" inputMode="numeric" value={row.passive ?? ""} onChange={(e) => onChange(m, { ...row, passive: e.target.value === "" ? null : Number(e.target.value) })} className="mx-auto text-center rounded-lg px-1 py-1.5 text-[14px]" style={{ width: 56, border: `1px solid ${T.border}` }} />
            </div>
            {ref && <div className="text-[10.5px] mt-1" style={{ color: T.inkSoft }}>Normal: {ref}</div>}
          </div>
        );
      })}
    </div>
  );
}

/* Single-value measurement list — e.g. ROM recorded as one figure per motion
   rather than active/passive pairs. Reusable wherever a template lists bounded
   numeric fields without a two-column structure. */
function NumberGroup({ items, values, onChange, suffix, region }) {
  const refs = ROM_REFERENCE[region] || {};
  return (
    <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${T.border}` }}>
      {items.map((m, i) => {
        const ref = refs[m];
        return (
          <div key={m} className="px-3 py-2.5" style={{ background: i % 2 ? T.surface : "#FAFCFC", borderTop: i ? `1px solid ${T.border}` : "none" }}>
            <div className="flex items-center justify-between">
              <span className="text-[13.5px]" style={{ color: T.ink }}>{m}</span>
              <div className="flex items-center gap-1">
                <input type="number" inputMode="numeric" value={values[m] ?? ""} onChange={(e) => onChange(m, e.target.value === "" ? null : Number(e.target.value))} className="text-right rounded-lg px-2 py-1.5 text-[14px] font-medium" style={{ width: 64, border: `1px solid ${T.border}` }} />
                {suffix && <span className="text-[13px]" style={{ color: T.inkSoft }}>{suffix}</span>}
              </div>
            </div>
            {ref && <div className="text-[10.5px] mt-0.5" style={{ color: T.inkSoft }}>Normal: {ref}</div>}
          </div>
        );
      })}
    </div>
  );
}

/* True matrix input — rows × columns of small numeric cells (e.g. digit ×
   joint contracture measurements). Distinct from NumberGroup, which is a
   single-column list; use this whenever a template presents an actual grid
   with two independent axes. */
function MeasurementGrid({ rows, columns, values, onChange, suffix }) {
  return (
    <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${T.border}` }}>
      <div
        className="grid text-[10.5px] font-semibold uppercase tracking-wide px-2 py-2"
        style={{ gridTemplateColumns: `1.1fr repeat(${columns.length}, 1fr)`, background: T.tealTint, color: T.tealDark }}
      >
        <span></span>
        {columns.map((c) => (
          <span key={c} className="text-center">{c}</span>
        ))}
      </div>
      {rows.map((r, i) => {
        const rowVals = values[r] || {};
        return (
          <div
            key={r}
            className="grid items-center px-2 py-1.5"
            style={{ gridTemplateColumns: `1.1fr repeat(${columns.length}, 1fr)`, background: i % 2 ? T.surface : "#FAFCFC", borderTop: `1px solid ${T.border}` }}
          >
            <span className="text-[12.5px]" style={{ color: T.ink }}>{r}</span>
            {columns.map((c) => (
              <input
                key={c}
                type="number"
                inputMode="numeric"
                value={rowVals[c] ?? ""}
                onChange={(e) => onChange(r, c, e.target.value === "" ? null : Number(e.target.value))}
                className="mx-auto text-center rounded-lg px-1 py-1.5 text-[13px]"
                style={{ width: 46, border: `1px solid ${T.border}` }}
              />
            ))}
          </div>
        );
      })}
      {suffix && (
        <div className="px-2 py-1.5 text-[11px]" style={{ color: T.inkSoft, borderTop: `1px solid ${T.border}` }}>
          Values in {suffix}
        </div>
      )}
    </div>
  );
}

function StrengthGrid({ muscles, values, onChange }) {
  return (
    <div className="flex flex-col gap-3">
      {muscles.map((m) => (
        <div key={m.key}>
          <div className="text-[13px] mb-1.5" style={{ color: T.ink }}>{m.label}</div>
          <div className="grid grid-cols-6 gap-1.5">
            {[0, 1, 2, 3, 4, 5].map((g) => {
              const active = values[m.key] === g;
              return (
                <button key={g} onClick={() => onChange(m.key, active ? null : g)} className="rounded-lg py-2 text-[14px] font-semibold active:scale-95 transition" style={{ minHeight: 40, background: active ? T.teal : T.slateChip, color: active ? "#fff" : T.ink, border: `1px solid ${active ? T.teal : T.border}` }}>
                  {g}
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

/* Branching pathway flow — reused across every condition's Management Pathway */
function PathwayFlow({ schema, answers, onAnswer, priorTreatmentGiven }) {
  const { effectiveStart, skipped } = skipCompletedInfoSteps(schema, priorTreatmentGiven);
  const trail = [];
  let currentId = effectiveStart;
  let guard = 0;
  while (currentId && guard < 50) {
    guard++;
    const node = schema.nodes[currentId];
    trail.push({ id: currentId, node });
    if (node.type === "info") currentId = node.next;
    else if (node.type === "question") {
      const ans = answers[currentId];
      if (!ans) break;
      const branch = node.options.find((o) => o.label === ans);
      currentId = branch ? branch.next : null;
    } else break;
  }
  const toneColors = { green: { bg: T.greenTint, fg: T.green, border: T.green }, teal: { bg: T.tealTint, fg: T.tealDark, border: T.teal }, amber: { bg: T.amberTint, fg: T.amber, border: T.amber } };
  return (
    <div className="flex flex-col">
      {skipped.length > 0 && (
        <div className="rounded-xl px-4 py-3 mb-3" style={{ background: T.slateChip, border: `1px dashed ${T.borderStrong}` }}>
          <div className="text-[12px] font-semibold uppercase tracking-wide mb-1.5" style={{ color: T.inkSoft }}>Already addressed, based on history</div>
          {skipped.map((s) => (
            <div key={s.id} className="text-[13px] mb-1 last:mb-0" style={{ color: T.inkSoft }}>{s.node.text}</div>
          ))}
        </div>
      )}
      {trail.map(({ id, node }, i) => (
        <div key={id} className="flex flex-col">
          <div className="rounded-xl px-4 py-3" style={{ background: node.type === "terminal" ? toneColors[node.tone]?.bg || T.slateChip : T.slateChip, border: `1px solid ${node.type === "terminal" ? toneColors[node.tone]?.border || T.border : T.border}` }}>
            <div className="text-[13px] font-semibold mb-0.5" style={{ color: node.type === "terminal" ? toneColors[node.tone]?.fg || T.ink : T.ink }}>{node.title}</div>
            <div className="text-[13.5px]" style={{ color: T.inkSoft }}>{node.text}</div>
            {node.type === "question" && (
              <div className="flex gap-2 mt-3">
                {node.options.map((o) => {
                  const active = answers[id] === o.label;
                  return (
                    <button key={o.label} onClick={() => onAnswer(id, o.label)} className="flex-1 rounded-lg py-2.5 text-[14px] font-semibold active:scale-95 transition" style={{ minHeight: 44, background: active ? T.teal : T.surface, color: active ? "#fff" : T.ink, border: `1px solid ${active ? T.teal : T.borderStrong}` }}>
                      {o.label}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
          {i < trail.length - 1 && <div className="flex justify-start pl-6"><div style={{ width: 2, height: 16, background: T.borderStrong }} /></div>}
        </div>
      ))}
    </div>
  );
}

/* Red-flag checklist — used both inline (section 10) and in the pinned drawer */
function RedFlagChecklist({ items, checked, onToggle }) {
  return (
    <>
      {items.map((rf, i) => {
        const active = checked.includes(i);
        return (
          <button key={i} onClick={() => onToggle(i)} className="w-full text-left rounded-xl px-3 py-3 mb-2 flex gap-3 items-start active:opacity-80" style={{ background: active ? T.redTint : T.slateChip, border: `1px solid ${active ? T.red : T.border}` }}>
            <span className="mt-0.5 shrink-0">{active ? <CheckCircle2 size={18} color={T.red} /> : <Circle size={18} color={T.borderStrong} />}</span>
            <span>
              <div className="text-[14px] font-medium" style={{ color: T.ink }}>{rf.text}</div>
              <div className="text-[13px] mt-0.5" style={{ color: active ? T.red : T.inkSoft }}>→ {rf.consider}</div>
            </span>
          </button>
        );
      })}
    </>
  );
}

function RedFlagPanel({ redFlags, checked, onToggle, urgentFlags, urgentChecked, onToggleUrgent, open, onClose, reviewed, onToggleReviewed }) {
  if (!open) return null;
  const hasUrgent = urgentFlags && urgentFlags.length > 0;
  const noFlagsChecked = (checked || []).length === 0 && (urgentChecked || []).length === 0;
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center" style={{ background: "rgba(16,30,43,0.45)" }}>
      <div className="w-full sm:max-w-md rounded-t-2xl sm:rounded-2xl" style={{ background: T.surface, maxHeight: "85vh", overflowY: "auto", WebkitOverflowScrolling: "touch", boxShadow: "0 -4px 24px rgba(16,30,43,0.12)" }}>
        <div className="flex items-center gap-2 px-4 py-4 sticky top-0" style={{ background: T.amberTint, borderBottom: `1px solid ${T.amber}` }}>
          <AlertTriangle size={20} color={T.amber} />
          <span className="font-bold text-[15px] flex-1" style={{ color: T.amber }}>Red Flags</span>
          <button onClick={onClose} className="p-1 active:opacity-60"><X size={20} color={T.amber} /></button>
        </div>
        <div className="px-4 py-3">
          {hasUrgent && (
            <>
              <div className="text-[12px] font-bold uppercase tracking-wide mb-2" style={{ color: T.red }}>Urgent — reassess immediately</div>
              <RedFlagChecklist items={urgentFlags} checked={urgentChecked} onToggle={onToggleUrgent} />
              <div className="text-[12px] font-bold uppercase tracking-wide mb-2 mt-4" style={{ color: T.amber }}>When to stop and reconsider</div>
            </>
          )}
          <RedFlagChecklist items={redFlags} checked={checked} onToggle={onToggle} />
          {noFlagsChecked && onToggleReviewed && (
            <button
              onClick={onToggleReviewed}
              className="w-full flex items-center gap-2.5 rounded-xl px-4 py-3.5 mt-4 text-left active:scale-95 transition"
              style={{ background: reviewed ? T.greenTint : T.slateChip, border: `1px solid ${reviewed ? T.green : T.border}` }}
            >
              {reviewed ? <CheckCircle2 size={20} color={T.green} /> : <Circle size={20} color={T.borderStrong} />}
              <span className="text-[14px] font-semibold" style={{ color: reviewed ? T.green : T.ink }}>Red flags reviewed — none present</span>
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================================
   GENERIC FIELD ENGINE
   One renderer + one note-formatter per field type. New conditions plug into
   this without touching any component code.
============================================================================ */
function isFilled(field, state) {
  switch (field.type) {
    case "checkbox": return (state[field.key] || []).length > 0;
    case "select": return !!state[field.key];
    case "text": return !!(state[field.key] && state[field.key].trim());
    case "date": return !!(state[field.key] && state[field.key].trim());
    case "number": return state[field.key] != null;
    case "vas": return (state[field.key] || 0) > 0;
    case "rom": { const v = state[field.key] || {}; return state[`${field.key}Full`] === "Full" || Object.values(v).some((r) => r && (r.active != null || r.passive != null)); }
    case "numberGroup": { const v = state[field.key] || {}; return Object.values(v).some((n) => n != null); }
    case "grid": { const v = state[field.key] || {}; return Object.values(v).some((row) => row && Object.values(row).some((n) => n != null)); }
    case "testGrid": return Object.keys(state[field.key] || {}).length > 0;
    case "strength": { const v = state[field.key] || {}; return Object.values(v).some((g) => g != null); }
    case "redflag": return (state[field.key] || []).length > 0 || !!state.redFlagsReviewed;
    case "pathway": return Object.keys(state[field.key] || {}).length > 0;
    case "conditional": return field.when(state) && field.fields.some((f) => isFilled(f, state));
    default: return false;
  }
}

function Field({ field, state, setField, region }) {
  if (field.type === "conditional") {
    if (!field.when(state)) return null;
    return <>{field.fields.map((f, i) => <Field key={i} field={f} state={state} setField={setField} region={region} />)}</>;
  }
  switch (field.type) {
    case "info":
      return (
        <>
          <SubLabel>{field.title}</SubLabel>
          <ul className="text-[13.5px] pl-4 mb-1" style={{ color: T.inkSoft, listStyle: "disc" }}>
            {field.items.map((x) => <li key={x}>{x}</li>)}
          </ul>
        </>
      );
    case "table":
      return (
        <>
          <SubLabel>{field.title}</SubLabel>
          {field.rows.map((r) => (
            <div key={r.left} className="flex gap-3 py-2" style={{ borderBottom: `1px solid ${T.border}` }}>
              <span className="text-[13px] font-semibold shrink-0" style={{ color: T.tealDark, width: 108 }}>{r.left}</span>
              <span className="text-[13.5px]" style={{ color: T.ink }}>{r.right}</span>
            </div>
          ))}
        </>
      );
    case "checkbox":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <CheckboxGroup options={field.options} selected={state[field.key] || []} onChange={(v) => setField(field.key, v)} />
        </>
      );
    case "testGrid":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <TestGrid tests={field.options} values={state[field.key] || {}} onChange={(t, v) => { const next = { ...(state[field.key] || {}) }; if (v === null) delete next[t]; else next[t] = v; setField(field.key, next); }} />
        </>
      );
    case "select":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <ButtonSelect options={field.options} value={state[field.key] || null} onChange={(v) => setField(field.key, v)} columns={field.columns} />
        </>
      );
    case "text":
      return <TextField label={field.label} value={state[field.key]} onChange={(v) => setField(field.key, v)} placeholder={field.placeholder} />;
    case "date":
      return <DateField label={field.label} value={state[field.key]} onChange={(v) => setField(field.key, v)} />;
    case "number":
      return <NumberField label={field.label} value={state[field.key]} onChange={(v) => setField(field.key, v)} suffix={field.suffix} />;
    case "vas":
      return (
        <>
          <SubLabel>Pain</SubLabel>
          <VASSlider value={state[field.key] || 0} onChange={(v) => setField(field.key, v)} />
        </>
      );
    case "rom": {
      const fullKey = `${field.key}Full`;
      const isFull = state[fullKey] === "Full";
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <ButtonSelect options={["Full", "Not full"]} value={state[fullKey] || null} onChange={(v) => setField(fullKey, v)} columns={2} />
          {!isFull && (
            <ROMTable motions={field.motions} values={state[field.key] || {}} onChange={(m, v) => setField(field.key, { ...(state[field.key] || {}), [m]: v })} region={region} />
          )}
        </>
      );
    }
    case "numberGroup":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <NumberGroup items={field.items} suffix={field.suffix} values={state[field.key] || {}} onChange={(m, v) => setField(field.key, { ...(state[field.key] || {}), [m]: v })} region={region} />
        </>
      );
    case "grid":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <MeasurementGrid
            rows={field.rows}
            columns={field.columns}
            suffix={field.suffix}
            values={state[field.key] || {}}
            onChange={(r, c, v) =>
              setField(field.key, {
                ...(state[field.key] || {}),
                [r]: { ...((state[field.key] || {})[r] || {}), [c]: v },
              })
            }
          />
        </>
      );
    case "strength":
      return (
        <>
          <SubLabel>{field.label}</SubLabel>
          <StrengthGrid muscles={field.muscles} values={state[field.key] || {}} onChange={(k, v) => setField(field.key, { ...(state[field.key] || {}), [k]: v })} />
        </>
      );
    case "pathway":
      return (
        <>
          <SubLabel>{field.title}</SubLabel>
          {field.introText && <div className="text-[12.5px] mb-3 italic" style={{ color: T.inkSoft }}>{field.introText}</div>}
          <PathwayFlow
            schema={field.schema}
            answers={state[field.key] || {}}
            onAnswer={(q, a) => setField(field.key, { ...(state[field.key] || {}), [q]: a })}
          />
        </>
      );
    default:
      return null;
  }
}

/* ============================================================================
   PROSE CLINIC NOTE GENERATOR
   Produces a natural-language note in a fixed section order (Patient,
   History, Examination, Imaging, Red Flags, Differential Diagnosis,
   Impression, Management Plan, Review Plan), built generically from any
   condition's schema + entered state — not a key:value printout. Only
   sections with actual data are included. This works uniformly across every
   condition object in this file because they all share the same section-id
   skeleton (typical/history/exam/imaging/differential/diagnosis/pathway/
   followup/outcomes/redflags/research).
============================================================================ */

// The modern Clipboard API frequently fails silently inside a sandboxed
// iframe (which is how this app runs when embedded as an artifact) - no
// exception the caller can act on, it just doesn't copy anything. Falls
// back to the older selection-based execCommand approach, which works in
// more restrictive embedded contexts, before giving up.
async function copyTextRobust(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (e) {
      // fall through to the legacy approach below
    }
  }
  try {
    const textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.style.position = "fixed";
    textarea.style.left = "-9999px";
    textarea.style.top = "0";
    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(textarea);
    if (!ok) throw new Error("execCommand copy failed");
    return true;
  } catch (e) {
    return false;
  }
}

function lowerListItem(item) {
  if (typeof item !== "string" || !item) return item;
  if (/^[A-Z]{2,}/.test(item)) return item;
  if (/^\d/.test(item)) return item;
  if (/^[A-Z]'/.test(item)) return item;
  if (EPONYM_TERMS_RE.test(item)) return item;
  return item.charAt(0).toLowerCase() + item.slice(1);
}

function humanizeList(items, opts) {
  const preserveCase = opts && opts.preserveCase;
  const arr = (items || []).filter(Boolean).map((it) => (preserveCase ? it : lowerListItem(it)));
  if (arr.length === 0) return "";
  if (arr.length === 1) return arr[0];
  if (arr.length === 2) return `${arr[0]} and ${arr[1]}`;
  return `${arr.slice(0, -1).join(", ")}, and ${arr[arr.length - 1]}`;
}

function lowerFirst(s) {
  if (!s || typeof s !== "string") return s;
  return s.charAt(0).toLowerCase() + s.slice(1);
}

// Expands "conditional" field wrappers according to current state, so
// callers see a flat list of fields actually visible/relevant right now.
function resolveFields(fields, state) {
  const out = [];
  for (const f of fields || []) {
    if (f.type === "conditional") {
      if (f.when(state)) out.push(...resolveFields(f.fields, state));
    } else {
      out.push(f);
    }
  }
  return out;
}

function joinClausesLower(clauses) {
  const list = (clauses || []).filter(Boolean);
  if (!list.length) return "";
  return list.join("; ") + ".";
}

// Converts one filled field into a short lowercase clause for embedding in
// a sentence (e.g. "symptoms included night pain and weakness"), using a
// small dictionary of key-pattern-based phrasings for the field-key
// conventions reused throughout this project's condition library, with a
// generic "label: value" fallback for anything unrecognized so the engine
// never breaks on an unfamiliar field.
function fieldClause(field, state) {
  if (field.type === "info" || field.type === "table") return null;
  if (!isFilled(field, state)) return null;
  const key = field.key || "";
  const label = field.noteLabel || field.label || "";
  // Field labels are Title-Case UI text (e.g. "Cervical Spine Screening");
  // embedded mid-sentence in the generic fallbacks below, every word needs
  // lowering, not just the first letter, or "Cervical Spine Screening
  // included Spurling" reads with inconsistent casing. Abbreviations and
  // eponyms within the label are still protected.
  const lowerLabel = label ? label.split(" ").map(lowerListItem).join(" ") : label;

  switch (field.type) {
    case "checkbox": {
      // A handful of special/provocative-test checklists predate the
      // testGrid field type and still use plain checkboxes (key prefix
      // "st" + capital, e.g. stRotatorCuff, stBiceps, stCervical) - their
      // options are named clinical signs (Jobe, Hornblower, Spurling),
      // proper nouns that must never be lowercased, unlike ordinary
      // descriptive checkbox options elsewhere.
      const isNamedTestList = /^st[A-Z]/.test(key) && key !== "stNeuro";
      // If "Other" is checked and a companion {key}Other text field has an
      // actual value, substitute it in place of the literal word "Other"
      // so the note reads the clinician's specific finding rather than a
      // meaningless placeholder.
      const otherText = state[`${key}Other`];
      const rawItems = (state[key] || []).map((item) => (item === "Other" && otherText && otherText.trim() ? otherText.trim() : item));
      const list = humanizeList(rawItems, { preserveCase: isNamedTestList });
      if (!list) return null;
      if (/^typicalPresentation/i.test(key)) return `the presentation was consistent with ${list}`;
      if (/affectedDigit/i.test(key)) return `this affects the ${list} digit${(state[key] || []).length === 1 ? "" : "s"}`;
      if (/symptom/i.test(key)) return `symptoms included ${list}`;
      if (/functionalLimit/i.test(key)) return `functional limitation was reported with ${list}`;
      if (/prevTreatment/i.test(key)) return `previous treatment included ${list}`;
      if (/(medHistory|relevantHistory)/i.test(key)) return `relevant medical history included ${list}`;
      if (/riskFactor/i.test(key)) return `relevant risk factors included ${list}`;
      if (/mechanismOfInjury/i.test(key)) return `the mechanism of injury was ${list}`;
      if (/injuryFactors/i.test(key)) return `injury factors included ${list}`;
      if (/(patientGoals|patientPriorities)/i.test(key)) return `the patient's goals included ${list}`;
      if (/inspection/i.test(key)) return `inspection revealed ${list}`;
      if (/palpation/i.test(key)) return `palpation was notable for ${list}`;
      if (/abnormal in$/i.test(label)) return `abnormal findings were noted in ${list}`;
      if (label) {
        // Labels of the form "Special tests — Rotator Cuff" read awkwardly
        // when dropped straight into a sentence ("special tests — rotator
        // cuff included Jobe"), so the qualifier is promoted to the front.
        const subGrouped = label.match(/^special tests\s*\u2014\s*(.+)$/i);
        if (subGrouped) {
          const qualifier = subGrouped[1].replace(/\s*\([^)]*\)\s*$/, "").trim();
          // Word-by-word so "Rotator Cuff" -> "rotator cuff" while
          // abbreviations like "AC" are still protected by lowerListItem.
          const lowered = qualifier.split(" ").map(lowerListItem).join(" ");
          return `${lowered} tests included ${list}`;
        }
        return `${lowerLabel} included ${list}`;
      }
      return list;
    }
    case "testGrid": {
      const results = state[key] || {};
      const positives = Object.keys(results).filter((t) => results[t] === "positive");
      const negatives = Object.keys(results).filter((t) => results[t] === "negative");
      const clauses = [];
      if (positives.length) clauses.push(`${humanizeList(positives, { preserveCase: true })} ${positives.length === 1 ? "was" : "were"} positive`);
      if (negatives.length) clauses.push(`${humanizeList(negatives, { preserveCase: true })} ${negatives.length === 1 ? "was" : "were"} negative`);
      if (!clauses.length) return null;
      // Same "Special tests — Rotator Cuff" -> "rotator cuff tests" promotion
      // used for the plain-checkbox fallback, so testGrid-typed special
      // tests read consistently rather than with the raw label prefix.
      const subGrouped = label.match(/^special tests\s*\u2014\s*(.+)$/i);
      if (subGrouped) {
        const qualifier = subGrouped[1].replace(/\s*\([^)]*\)\s*$/, "").trim();
        const lowered = qualifier.split(" ").map(lowerListItem).join(" ");
        return `${lowered} tests: ${clauses.join("; ")}`;
      }
      return `${lowerLabel}: ${clauses.join("; ")}`;
    }
    case "select": {
      const v = state[key];
      if (!v) return null;
      if (/^side$/i.test(key)) return `this affects the ${v.toLowerCase()} side`;
      if (/dominantArm|dominantHand/i.test(key)) return v === "Yes" ? "this is the dominant side" : "this is the non-dominant side";
      if (/^onset$/i.test(key)) return `onset was ${lowerFirst(v)}`;
      if (/^affectedDigit$/i.test(key)) return `this affects the ${lowerFirst(v)} digit`;
      if (/^treatmentResponse$/i.test(key)) return `the response to treatment was ${lowerListItem(v)}`;
      if (/symptomProgression/i.test(key)) return `symptoms have been ${v.toLowerCase()} since onset`;
      if (/^mechanism$/i.test(key)) return `the mechanism was ${lowerFirst(v)}`;
      if (/workDemand/i.test(key)) return `work demand is ${lowerFirst(v)}`;
      if (/activityLevel/i.test(key)) return `activity level is ${lowerFirst(v)}`;
      if (/neuro\w*Status$/i.test(key)) return `${lowerFirst(label.replace(/ \u2014 overall$/i, ""))} status was ${v.toLowerCase()}`;
      if (label) return `${lowerLabel} was ${lowerListItem(v)}`;
      return v;
    }
    case "text": {
      const v = state[key];
      if (!v || !v.trim()) return null;
      // A "{checkboxKey}Other" text field's value is substituted directly
      // into that checkbox's own clause (see the checkbox case above), so
      // it must not also produce a second, redundant standalone clause
      // here - only suppress when the sibling checkbox actually has
      // "Other" selected, so a same-named field used for an unrelated
      // purpose elsewhere isn't accidentally swallowed.
      const otherMatch = key.match(/^(\w+)Other$/);
      if (otherMatch && Array.isArray(state[otherMatch[1]]) && state[otherMatch[1]].includes("Other")) return null;
      if (/^occupation/i.test(key)) return `works as a ${v}`;
      if (/^(sport|hobby|hobbies|sportHobby)$/i.test(key)) return `participates in ${v}`;
      if (/notable finding$/i.test(label)) return v;
      if (label) return `${lowerLabel}: ${v}`;
      return v;
    }
    case "date": {
      const v = state[key];
      if (!v || !v.trim()) return null;
      if (/^injuryDate$/i.test(key)) return `the injury occurred on ${v}`;
      return `${lowerLabel || "date"} was ${v}`;
    }
    case "number": {
      const v = state[key];
      if (v == null) return null;
      const suffix = field.suffix ? ` ${field.suffix}` : "";
      if (label) return `${lowerLabel} was ${v}${suffix}`;
      return `${v}${suffix}`;
    }
    case "vas": {
      const v = state[key];
      if (!v) return null;
      return `pain was rated ${v}/10`;
    }
    case "rom": {
      if (state[`${key}Full`] === "Full") return "range of motion was full";
      const v = state[key] || {};
      const parts = Object.entries(v)
        .filter(([, r]) => r && (r.active != null || r.passive != null))
        .map(([m, r]) => {
          const bits = [];
          if (r.active != null) bits.push(`${r.active}\u00b0 actively`);
          if (r.passive != null) bits.push(`${r.passive}\u00b0 passively`);
          return `${m} was ${bits.join(" and ")}`;
        });
      return parts.length ? parts.join("; ") : null;
    }
    case "numberGroup": {
      const v = state[key] || {};
      const suffix = field.suffix || "";
      const parts = Object.entries(v).filter(([, n]) => n != null).map(([m, n]) => `${m} was ${n}${suffix}`);
      return parts.length ? parts.join("; ") : null;
    }
    case "grid": {
      const v = state[key] || {};
      const suffix = field.suffix || "";
      const rowParts = [];
      for (const r of Object.keys(v)) {
        const rowVals = v[r] || {};
        const cellParts = Object.entries(rowVals).filter(([, n]) => n != null).map(([c, n]) => `${c} ${n}${suffix}`);
        if (cellParts.length) rowParts.push(`${r} \u2014 ${cellParts.join(", ")}`);
      }
      return rowParts.length ? rowParts.join("; ") : null;
    }
    case "strength": {
      const v = state[key] || {};
      const muscles = field.muscles || [];
      const parts = muscles.filter((m) => v[m.key] != null).map((m) => `${m.label} was graded ${v[m.key]}/5`);
      return parts.length ? parts.join("; ") : null;
    }
    default:
      return null;
  }
}

const DEMOGRAPHIC_KEY_RE = /^(age|side|gender|dominantArm|dominantHand|dominantHandSide|occupation|occupationBeforeInjury|activityLevel|workDemand|medHistory|relevantHistory|prevSurgery)$/i;

// Resolves absolute hand dominance (Right/Left) for the "patient is X hand
// dominant" statement. Most templates only ask "is the affected side
// dominant?" (Yes/No) rather than which hand is dominant outright, so this
// derives the absolute answer from that plus which side is affected; a
// minority of templates ask for the absolute side directly, which is used
// as-is when present. Bilateral involvement or missing data means this
// can't be reliably resolved, so it's simply omitted rather than guessed.
function resolveDominantHandSide(side, dominantHandSide, domRelative) {
  if (dominantHandSide === "Right" || dominantHandSide === "Left") return dominantHandSide;
  if ((domRelative === "Yes" || domRelative === "No") && (side === "Right" || side === "Left")) {
    if (domRelative === "Yes") return side;
    return side === "Right" ? "Left" : "Right";
  }
  return null;
}

function buildDemographics(condition, state) {
  const allFields = resolveFields(condition.sections.flatMap((s) => s.fields || []), state);
  const val = (re) => {
    const f = allFields.find((ff) => re.test(ff.key || ""));
    return f ? state[f.key] : null;
  };
  const age = val(/^age$/i);
  const gender = val(/^gender$/i);
  const side = val(/^side$/i);
  const domRelative = val(/^dominantArm$|^dominantHand$/i);
  const dominantHandSide = val(/^dominantHandSide$/i);
  const occ = val(/^occupation$/i) || val(/^occupationBeforeInjury$/i);
  const activity = val(/^activityLevel$/i);
  const work = val(/^workDemand$/i);
  const medHistoryItems = val(/^medHistory$/i) || val(/^relevantHistory$/i);
  const prevSurgery = val(/^prevSurgery$/i);

  const sentences = [];

  // Sentence 1: age, gender, and any known past medical history. Smoking
  // is excluded here since it's tracked as a risk factor elsewhere in the
  // note (History section) rather than restated as part of this summary.
  const diagnoses = (medHistoryItems || []).filter((item) => typeof item === "string" && !/smoking/i.test(item));
  let opening = null;
  if (age && gender) opening = `The patient is a ${age}-year-old ${String(gender).toLowerCase()}`;
  else if (age) opening = `The patient is ${age} years old`;
  else if (gender) opening = `The patient is ${String(gender).toLowerCase()}`;
  if (opening) {
    if (diagnoses.length) opening += `, with known history of ${humanizeList(diagnoses)}`;
    sentences.push(`${opening}.`);
  } else if (diagnoses.length) {
    sentences.push(`The patient has a known history of ${humanizeList(diagnoses)}.`);
  }

  // Sentence 2: occupation and work demand, with a pronoun matching the
  // patient's recorded gender (falling back to "The patient" if gender
  // isn't documented, rather than guessing).
  if (occ && typeof occ === "string" && occ.trim()) {
    const pronoun = gender === "Male" ? "He" : gender === "Female" ? "She" : "The patient";
    let workSentence = `${pronoun} works as ${/^[aeiou]/i.test(occ.trim()) ? "an" : "a"} ${occ.trim()}`;
    if (work) workSentence += ` with a ${String(work).toLowerCase()} workload`;
    sentences.push(`${workSentence}.`);
  } else if (work) {
    sentences.push(`Work demand is ${String(work).toLowerCase()}.`);
  }

  // Sentence 3: hand dominance, stated directly rather than "dominant side
  // affected" - this needs its own sentence since it's a standing fact
  // about the patient, not something tied to laterality of presentation.
  const resolvedDominance = resolveDominantHandSide(side, dominantHandSide, domRelative);
  if (resolvedDominance) sentences.push(`The patient is ${resolvedDominance.toLowerCase()} hand dominant.`);

  // Remaining context: previous surgery, activity level - kept as brief
  // trailing sentences so nothing already captured is lost from the
  // redesign above. Which side is affected (bilateral or unilateral) is
  // stated in the presenting complaint (History section) instead of here,
  // since it's part of describing the complaint itself rather than patient
  // demographics.
  if (prevSurgery && typeof prevSurgery === "string" && prevSurgery.trim() && !/^none$/i.test(prevSurgery.trim())) {
    sentences.push(`Previous surgical history: ${prevSurgery.trim()}.`);
  }
  if (activity) sentences.push(`Activity level is ${String(activity).toLowerCase()}.`);

  return sentences.length ? sentences.join(" ") : null;
}

// Groups history clauses into themed sub-paragraphs (presenting complaint,
// symptoms, functional limitation, previous treatment, background/risk
// factors, then anything left over) rather than one long semicolon-chained
// sentence, mirroring how buildExamination groups exam findings. Grouping
// is by field-key pattern and field type - the same vocabulary fieldClause
// already recognizes - so it works generically across every template
// without any condition-specific logic.
function emptyHistoryGroups() {
  return { presenting: [], symptoms: [], function: [], treatment: [], background: [], other: [] };
}

function historyGroupsFor(fields, state) {
  const groups = emptyHistoryGroups();

  resolveFields(fields, state).forEach((f) => {
    if (DEMOGRAPHIC_KEY_RE.test(f.key || "")) return;
    const key = f.key || "";
    if (/^typicalPresentation/i.test(key)) return; // handled as its own leading sentence in buildHistory
    const c = fieldClause(f, state);
    if (!c) return;
    if (/mechanismOfInjury/i.test(key) || /injuryFactors/i.test(key) || /^mechanism$/i.test(key) || /^onset$/i.test(key) || /duration/i.test(key) || /timeSinceInjury/i.test(key) || /symptomProgression/i.test(key) || /affectedDigit/i.test(key) || f.type === "vas" || f.type === "date") {
      groups.presenting.push(c);
    } else if (/symptom/i.test(key) || /painChar/i.test(key)) {
      groups.symptoms.push(c);
    } else if (/functionalLimit/i.test(key) || /(patientGoals|patientPriorities)/i.test(key)) {
      groups.function.push(c);
    } else if (/prevTreatment/i.test(key) || /treatmentResponse/i.test(key)) {
      groups.treatment.push(c);
    } else if (/(medHistory|relevantHistory)/i.test(key) || /riskFactor/i.test(key)) {
      groups.background.push(c);
    } else {
      groups.other.push(c);
    }
  });

  return groups;
}

// Combines multiple group sets (e.g. Typical Patient's fields + History's
// fields) into one, so their "presenting complaint" content is reported in
// a single sentence rather than two separate "The patient presents with..."
// sentences back to back.
function mergeHistoryGroups(...groupsList) {
  const merged = emptyHistoryGroups();
  groupsList.forEach((g) => {
    if (!g) return;
    Object.keys(merged).forEach((k) => merged[k].push(...g[k]));
  });
  return merged;
}

function historyGroupsToText(groups) {
  const bullets = [];
  if (groups.presenting.length) bullets.push(`\u2022 Presenting complaint: ${joinClausesLower(groups.presenting)}`);
  if (groups.symptoms.length) bullets.push(`\u2022 Symptoms: ${joinClausesLower(groups.symptoms)}`);
  if (groups.function.length) bullets.push(`\u2022 Functional limitation: ${joinClausesLower(groups.function)}`);
  if (groups.treatment.length) bullets.push(`\u2022 Previous treatment: ${joinClausesLower(groups.treatment)}`);
  if (groups.background.length) bullets.push(`\u2022 Background: ${joinClausesLower(groups.background)}`);
  if (groups.other.length) bullets.push(`\u2022 Other relevant history: ${joinClausesLower(groups.other)}`);
  return bullets.length ? bullets.join("\n") : null;
}

// Builds the standalone opening sentence of History from the Typical
// Patient section's typicalPresentation checklist, naming the body region
// explicitly rather than the previous "presentation was consistent with"
// phrasing - this reads as a proper clinical opening statement rather than
// a clause buried mid-list alongside duration and pain score.
function typicalPresentationSentence(typical, state, region) {
  if (!typical) return null;
  const field = resolveFields(typical.fields, state).find((f) => f.key && /^typicalPresentation/i.test(f.key));
  if (!field) return null;
  const items = state[field.key];
  if (!items || !items.length) return null;
  const regionLabel = region && REGIONS[region] ? REGIONS[region].label.toLowerCase() : null;
  return `The patient presented with ${regionLabel ? `${regionLabel} symptoms: ` : ""}${humanizeList(items)}.`;
}

function buildHistory(condition, state) {
  const typical = condition.sections.find((s) => s.id === "typical");
  const history = condition.sections.find((s) => s.id === "history");
  const typicalGroups = typical ? historyGroupsFor(typical.fields, state) : null;
  const openingSentence = typicalPresentationSentence(typical, state, condition.region);

  // Typical Patient content (risk factors etc.) is shared regardless of
  // laterality; History content is what's actually documented independently
  // per limb, so only that part splits into Right/Left bullet groups. The
  // unilateral case merges both sections' groups into one combined set so
  // "presenting complaint" content from either section reads as a single
  // bullet rather than two.
  if (state.side === "Bilateral" && history) {
    const rightState = { ...state, ...(state.limbData?.right || {}) };
    const leftState = { ...state, ...(state.limbData?.left || {}) };
    const rightGroups = historyGroupsFor(history.fields, rightState);
    const leftGroups = historyGroupsFor(history.fields, leftState);
    const parts = [];
    if (openingSentence) parts.push(openingSentence);
    parts.push("Bilateral involvement is present.");
    const typicalText = typicalGroups && historyGroupsToText(typicalGroups);
    if (typicalText) parts.push(typicalText);
    const rightText = historyGroupsToText(rightGroups);
    if (rightText) parts.push(`Right side:\n${rightText}`);
    const leftText = historyGroupsToText(leftGroups);
    if (leftText) parts.push(`Left side:\n${leftText}`);
    return parts.length ? parts.join("\n\n") : null;
  }

  const historyGroups = history ? historyGroupsFor(history.fields, state) : null;
  const mergedText = historyGroupsToText(mergeHistoryGroups(typicalGroups, historyGroups));
  const side = state.side;
  const sideStatement = side && String(side).toLowerCase() !== "bilateral" ? `The ${String(side).toLowerCase()} side is affected.` : null;
  // Opening sentence first, then laterality, then the rest of the grouped
  // history - each joined by a newline so the bulleted content starts
  // cleanly on its own line rather than running on from the sentence above.
  const leading = [openingSentence, sideStatement].filter(Boolean).join("\n");
  if (leading && mergedText) return `${leading}\n${mergedText}`;
  if (leading) return leading;
  return mergedText;
}

// Groups examination clauses into a handful of themed, labeled bullet
// points (inspection, palpation, motion/strength, special tests, then
// anything left over) instead of one long semicolon-chained sentence, so
// the exam reads as a scannable list at a glance rather than a paragraph
// the reader has to parse. Grouping is by field-key pattern and field type,
// not by anything condition-specific, so it works generically across every
// template.
function examinationTextFor(exam, state) {
  const fields = resolveFields(exam.fields, state);

  const groups = {
    inspection: [],
    palpation: [],
    motion: [],
    special: [],
    other: [],
  };

  fields.forEach((f) => {
    const c = fieldClause(f, state);
    if (!c) return;
    const key = f.key || "";
    if (/inspection/i.test(key)) groups.inspection.push(c);
    else if (/palpation/i.test(key)) groups.palpation.push(c);
    else if (f.type === "testGrid" || /(specialTest|provocat|impingement)/i.test(key) || /^stability[A-Z]/.test(key) || (/^st[A-Z]/.test(key) && key !== "stNeuro")) groups.special.push(c);
    else if (f.type === "rom" || f.type === "strength" || /(strength|rom|motion|romFollowUp)/i.test(key)) groups.motion.push(c);
    else groups.other.push(c);
  });

  const bullets = [];
  if (groups.inspection.length) bullets.push(`\u2022 Inspection: ${joinClausesLower(groups.inspection)}`);
  if (groups.palpation.length) bullets.push(`\u2022 Palpation: ${joinClausesLower(groups.palpation)}`);
  if (groups.motion.length) bullets.push(`\u2022 Range of motion and strength: ${joinClausesLower(groups.motion)}`);
  if (groups.special.length) bullets.push(`\u2022 Special tests: ${joinClausesLower(groups.special)}`);
  if (groups.other.length) bullets.push(`\u2022 Other findings: ${joinClausesLower(groups.other)}`);

  return bullets.length ? bullets.join("\n") : null;
}

function buildExamination(condition, state) {
  const exam = condition.sections.find((s) => s.id === "exam");
  if (!exam) return null;

  // Trigger finger: each affected digit is assessed independently (motion,
  // trigger severity, and A1 pulley findings genuinely differ digit to
  // digit), while inspection/associated-conditions/neurovascular remain
  // whole-hand findings assessed once.
  if (condition.id === "trigger-finger") {
    const digitSpecificKeys = new Set(["palpation", "activeFlexion", "activeExtension", "passiveMotion", "compositeFist", "tendonGliding", "triggerSeverity"]);
    const sharedSection = { fields: exam.fields.filter((f) => !digitSpecificKeys.has(f.key)) };
    const perDigitFieldsList = exam.fields.filter((f) => digitSpecificKeys.has(f.key));
    const sharedText = examinationTextFor(sharedSection, state);
    const parts = [];
    if (sharedText) parts.push(sharedText);
    (state.affectedDigits || []).forEach((digit) => {
      const digitText = examinationTextFor({ fields: perDigitFieldsList }, state.digitData?.[digit] || {});
      if (digitText) parts.push(`${digit}:\n${digitText}`);
    });
    return parts.length ? parts.join("\n\n") : null;
  }

  if (state.side === "Bilateral") {
    const rightState = { ...state, ...(state.limbData?.right || {}) };
    const leftState = { ...state, ...(state.limbData?.left || {}) };
    const rightText = examinationTextFor(exam, rightState);
    const leftText = examinationTextFor(exam, leftState);
    const parts = [];
    if (rightText) parts.push(`Right side:\n${rightText}`);
    if (leftText) parts.push(`Left side:\n${leftText}`);
    return parts.length ? parts.join("\n\n") : null;
  }

  return examinationTextFor(exam, state);
}

// Groups imaging clauses by modality (Radiographs, Ultrasound, MRI, CT,
// Arthroscopy, Electrodiagnostic studies) into separate sub-paragraphs
// rather than mixing every modality's findings into one sentence, since a
// consultant reading the note wants to know at a glance what the X-ray
// showed versus what the MRI showed. Modality detection uses the same
// pattern-matching this app already relies on elsewhere (e.g. the Imaging
// section's own "notable finding" fields), so it works generically across
// every template without hardcoding per-condition field names.
const IMAGING_MODALITY_ORDER = [
  { test: /radiograph|x-?ray/i, label: "Radiographs" },
  { test: /ultrasound/i, label: "Ultrasound" },
  { test: /\bmri\b/i, label: "MRI" },
  { test: /\bct\b/i, label: "CT" },
  { test: /arthroscop/i, label: "Arthroscopy" },
  { test: /electrodiagnostic|\bemg\b|\bncs\b/i, label: "Electrodiagnostic studies" },
];

// Some conditions' "which views were obtained" fields are labelled things
// like "Essential views obtained" or "Radiographs (routine) — views" with
// no literal word "radiograph" in the text at all, so label/key regex
// matching alone would miss them - these specific keys (identified when
// this app's Imaging sections were made interactive) are known to always
// represent radiograph views regardless of their exact label wording.
const IMAGING_RADIOGRAPH_VIEW_KEYS = new Set(["imgEssential", "imgViews", "imgRecommended", "imgRadiographs", "initialRadiographs"]);

function imagingTextFor(imaging, state) {
  const buckets = new Map();
  const other = [];

  resolveFields(imaging.fields, state).forEach((f) => {
    const c = fieldClause(f, state);
    if (!c) return;
    const key = f.key || "";
    let modalityLabel = null;
    if (IMAGING_RADIOGRAPH_VIEW_KEYS.has(key)) {
      modalityLabel = "Radiographs";
    } else {
      const text = [key, f.label, f.noteLabel].filter(Boolean).join(" ");
      const modality = IMAGING_MODALITY_ORDER.find((m) => m.test.test(text));
      modalityLabel = modality ? modality.label : null;
    }
    if (modalityLabel) {
      if (!buckets.has(modalityLabel)) buckets.set(modalityLabel, []);
      buckets.get(modalityLabel).push(c);
    } else {
      other.push(c);
    }
  });

  const sentences = [];
  IMAGING_MODALITY_ORDER.forEach((m) => {
    if (buckets.has(m.label)) sentences.push(`${m.label}: ${joinClausesLower(buckets.get(m.label))}`);
  });
  if (other.length) sentences.push(`Additional imaging: ${joinClausesLower(other)}`);

  return sentences.length ? sentences.join(" ") : null;
}

function buildImaging(condition, state) {
  const imaging = condition.sections.find((s) => s.id === "imaging");
  if (!imaging) return null;

  if (state.side === "Bilateral") {
    const rightState = { ...state, ...(state.limbData?.right || {}) };
    const leftState = { ...state, ...(state.limbData?.left || {}) };
    const rightText = imagingTextFor(imaging, rightState);
    const leftText = imagingTextFor(imaging, leftState);
    const parts = [];
    if (rightText) parts.push(`Right side \u2014 ${rightText}`);
    if (leftText) parts.push(`Left side \u2014 ${leftText}`);
    return parts.length ? parts.join(" ") : null;
  }

  return imagingTextFor(imaging, state);
}

// States plainly whether any red flags were identified. When nothing was
// checked, this is a single short sentence rather than a list of every
// possible red flag for the condition — a clinician reading the note wants
// to know the answer (none), not the full screening checklist. When
// something was checked, that's called out specifically since it's
// clinically actionable, without also naming every other flag that wasn't
// present. Rendered as its own section, not folded into examination.
function buildRedFlagsExcluded(condition, state) {
  const hasUrgent = condition.urgentFlags && condition.urgentFlags.length > 0;
  const hasStandard = condition.redFlags && condition.redFlags.length > 0;
  if (!hasUrgent && !hasStandard) return null;

  const urgentChecked = state.urgentFlagsChecked || [];
  const redChecked = state.redFlagsChecked || [];

  const presentItems = [
    ...(condition.urgentFlags || []).filter((_, i) => urgentChecked.includes(i)),
    ...(condition.redFlags || []).filter((_, i) => redChecked.includes(i)),
  ].map((f) => `${f.text} (${lowerFirst(f.consider)})`);

  if (!presentItems.length) {
    // Only asserted once the clinician has explicitly confirmed they
    // screened for red flags and found none - otherwise this section is
    // omitted rather than silently claiming a screening that may never
    // have happened.
    return state.redFlagsReviewed ? "Red flags reviewed: none present." : null;
  }

  return `The following concerning features were identified and require action: ${humanizeList(presentItems)}. All other red flags for this condition were screened for and excluded.`;
}

function buildDifferential(condition, state) {
  const diff = condition.sections.find((s) => s.id === "differential");
  if (!diff) return null;
  const field = resolveFields(diff.fields, state).find((f) => f.type === "checkbox");
  if (!field) return null;
  const list = state[field.key] || [];
  if (!list.length) return null;
  return `The following alternative diagnoses were considered and felt to be less likely: ${humanizeList(list, { preserveCase: true })}.`;
}

function impressionClausesFor(dx, state) {
  const clauses = [];
  resolveFields(dx.fields, state).forEach((f) => {
    const c = fieldClause(f, state);
    if (c) clauses.push(c);
  });
  return clauses;
}

function buildImpression(condition, state) {
  const dx = condition.sections.find((s) => s.id === "diagnosis");
  if (!dx) return null;

  if (state.side === "Bilateral") {
    const rightState = { ...state, ...(state.limbData?.right || {}) };
    const leftState = { ...state, ...(state.limbData?.left || {}) };
    const rightClauses = impressionClausesFor(dx, rightState);
    const leftClauses = impressionClausesFor(dx, leftState);
    const parts = [];
    if (rightClauses.length) parts.push(`Right side \u2014 ${joinClausesLower(rightClauses)}`);
    if (leftClauses.length) parts.push(`Left side \u2014 ${joinClausesLower(leftClauses)}`);
    return parts.length ? `Clinical impression: ${parts.join(" ")}` : null;
  }

  const clauses = impressionClausesFor(dx, state);
  if (!clauses.length) return null;
  return `Clinical impression: ${joinClausesLower(clauses)}`;
}

// Terms indicating the reached management plan involves an operative
// procedure, used to decide whether to append the surgery-discussion line
// below. Deliberately broad (covers repair, reconstruction, fixation,
// decompression, excision, arthroscopy, arthroplasty, grafts/transfers,
// osteotomy, fusion, replantation, etc.) since the plans across this
// project's conditions describe surgery in many different specific terms
// rather than one consistent word.
// Standard operative options per diagnosis, shown once the clinician has
// recorded that the patient agreed to discuss surgery. This is a fixed,
// clinician-curated list per condition (researched against current
// literature/guidelines where the choice of procedure is genuinely
// evidence-driven and actively discussed - e.g. rotator cuff repair
// technique, thumb CMC arthroplasty technique, cubital tunnel decompression
// vs transposition, shoulder instability fixation choice, lateral
// epicondylitis debridement approach), plus standard, well-established
// procedure names for conditions where the operative options are settled,
// textbook nomenclature (fracture fixation methods, tendon/nerve repair
// techniques) rather than an actively evolving evidence question. This is
// NOT live-searched at runtime - the app has no server or network access,
// so it can't perform a fresh literature search on its own; presenting
// invented or unverified citations as "current evidence" inside a clinical
// tool would be a patient-safety problem, so this list is deliberately just
// procedure names for the clinician to select from, with a free-text field
// for anything not listed, rather than any evidence-grading claims.
const SURGICAL_OPTIONS_BY_CONDITION = {
  // Shoulder
  "rotator-cuff": ["Arthroscopic rotator cuff repair", "Mini-open rotator cuff repair", "Open rotator cuff repair", "Partial repair / debridement", "Superior capsule reconstruction", "Tendon transfer (e.g. latissimus dorsi)", "Subacromial balloon spacer", "Reverse shoulder arthroplasty"],
  saps: ["Arthroscopic subacromial decompression", "Arthroscopic bursectomy", "Acromioplasty"],
  "adhesive-capsulitis": ["Manipulation under anaesthesia", "Arthroscopic capsular release", "Image-guided hydrodilatation"],
  "glenohumeral-instability": ["Arthroscopic Bankart repair", "Arthroscopic Bankart repair with remplissage", "Open Bankart repair", "Latarjet procedure (open)", "Latarjet procedure (arthroscopic)", "Glenoid bone grafting"],
  "long-head-biceps": ["Biceps tenotomy", "Biceps tenodesis (open)", "Biceps tenodesis (arthroscopic)"],
  "ac-joint": ["Arthroscopic distal clavicle excision", "Open distal clavicle excision (Mumford procedure)", "AC joint stabilization / reconstruction"],
  "gh-osteoarthritis": ["Total shoulder arthroplasty (anatomic)", "Reverse shoulder arthroplasty", "Hemiarthroplasty", "Arthroscopic debridement (CAM procedure)"],
  "avn-humeral-head": ["Core decompression", "Hemiarthroplasty", "Total shoulder arthroplasty", "Reverse shoulder arthroplasty"],
  "calcific-tendinitis": ["Arthroscopic removal of calcific deposit", "Ultrasound-guided needle barbotage / lavage"],
  "proximal-humerus-fracture": ["ORIF with locking plate", "Intramedullary nailing", "Percutaneous pinning", "Hemiarthroplasty", "Reverse shoulder arthroplasty"],
  "scapular-dyskinesis": ["Nerve decompression (if neurogenic cause identified)", "Muscle/tendon transfer (for scapular winging)", "Surgical treatment of identified underlying pathology"],
  "slap-lesion": ["Arthroscopic SLAP repair", "Biceps tenodesis", "Debridement alone"],
  "pec-major-rupture": ["Primary repair (acute)", "Reconstruction with graft (chronic/delayed)"],
  // Elbow
  "lateral-epicondylopathy": ["Open debridement/repair (ECRB)", "Arthroscopic debridement", "Percutaneous debridement/tenotomy"],
  "medial-epicondylopathy": ["Open debridement/repair (flexor-pronator origin)", "Percutaneous tenotomy"],
  "distal-biceps-rupture": ["Primary repair, single-incision technique", "Primary repair, two-incision technique", "Reconstruction with graft (chronic/delayed)"],
  "elbow-osteoarthritis": ["Arthroscopic debridement", "Open debridement (Outerbridge-Kashiwagi)", "Total elbow arthroplasty", "Ulnohumeral arthroplasty"],
  "distal-triceps-rupture": ["Primary repair", "Reconstruction with graft (chronic)"],
  "radial-head-fracture": ["ORIF", "Radial head excision", "Radial head arthroplasty"],
  "coronoid-terrible-triad": ["ORIF of coronoid", "ORIF or arthroplasty of radial head", "Lateral collateral ligament repair", "Hinged external fixation"],
  "elbow-instability": ["Ligament repair (LUCL/MCL)", "Ligament reconstruction", "Hinged external fixation"],
  "elbow-stiffness": ["Arthroscopic capsular release", "Open capsular release (column procedure)"],
  "athletic-elbow-ocd-veo": ["Arthroscopic debridement / microfracture (OCD)", "Osteochondral autograft/allograft transplantation", "UCL reconstruction", "Loose body removal"],
  // Wrist
  "de-quervain": ["Open first dorsal compartment release", "Endoscopic first dorsal compartment release"],
  "thumb-cmc-oa": ["Trapeziectomy alone", "Trapeziectomy with LRTI", "Trapeziectomy with suspensionplasty", "Suture suspensionplasty", "Prosthetic (implant) arthroplasty", "Arthrodesis"],
  "wrist-oa": ["Proximal row carpectomy", "Total wrist arthrodesis (fusion)", "Total wrist arthroplasty", "Limited (e.g. four-corner) fusion"],
  "tfcc-injury": ["Arthroscopic debridement", "Arthroscopic repair", "Open repair", "Ulnar shortening osteotomy"],
  "scapholunate-injury": ["Arthroscopic debridement / pinning", "Open ligament repair", "Ligament reconstruction (tenodesis)", "Scapholunate or limited fusion (salvage)"],
  "kienbock-disease": ["Radial shortening osteotomy", "Core decompression", "Revascularization procedure", "Proximal row carpectomy", "Partial or total wrist fusion (advanced stage)"],
  "ulnar-impaction": ["Ulnar shortening osteotomy", "Wafer procedure (arthroscopic or open)", "TFCC debridement"],
  "wrist-ganglion": ["Arthroscopic excision", "Open excision"],
  // Peripheral Nerve
  "carpal-tunnel-syndrome": ["Open carpal tunnel release", "Mini-open carpal tunnel release", "Endoscopic carpal tunnel release"],
  "cubital-tunnel-syndrome": ["In situ decompression (open)", "Endoscopic decompression", "Medial epicondylectomy", "Anterior transposition (subcutaneous)", "Anterior transposition (submuscular)"],
  "lacertus-syndrome": ["Open lacertus fibrosus release / proximal median nerve decompression"],
  "guyons-canal-syndrome": ["Open decompression of Guyon's canal", "Endoscopic decompression"],
  "radial-tunnel-syndrome": ["Open radial tunnel decompression"],
  "pin-syndrome": ["Open decompression of the posterior interosseous nerve", "Tendon transfer (if no recovery)"],
  "ain-syndrome": ["Open decompression of the anterior interosseous nerve", "Tendon transfer (if no recovery)"],
  "wartenberg-syndrome": ["Superficial radial nerve decompression"],
  "double-crush-syndrome": ["Decompression at each identified site (staged)", "Decompression at each identified site (combined)"],
  // Hand - General
  "trigger-finger": ["Open A1 pulley release", "Percutaneous A1 pulley release"],
  "dupuytren-disease": ["Limited/regional fasciectomy", "Dermofasciectomy", "Percutaneous needle aponeurotomy", "Collagenase injection (enzymatic fasciotomy)"],
  "mallet-finger": ["Extension block pinning", "ORIF (large bony fragment)", "Tendon repair (chronic)"],
  "jersey-finger": ["Primary tendon repair / reinsertion", "Staged tendon reconstruction (chronic)"],
  "sagittal-band-injury": ["Primary repair", "Reconstruction (chronic)"],
  "extensor-tendon-injuries": ["Primary repair", "Tendon grafting / reconstruction (delayed)"],
  // Hand & Wrist Trauma
  "distal-radius-fracture": ["ORIF with volar locking plate", "Percutaneous pinning", "External fixation", "Fragment-specific fixation"],
  "scaphoid-fracture": ["Percutaneous screw fixation", "Open reduction internal fixation", "Bone grafting (for nonunion)"],
  "thumb-ucl-injury": ["Primary ligament repair", "Ligament reconstruction (chronic/Stener lesion)"],
  "metacarpal-fracture": ["Closed reduction percutaneous pinning", "ORIF (plate/screws)", "Intramedullary fixation"],
  "phalangeal-fracture": ["Closed reduction percutaneous pinning", "ORIF", "External fixation"],
  "bennett-rolando-fracture": ["Closed reduction percutaneous pinning", "ORIF"],
  "perilunate-injury": ["Open reduction internal fixation with ligament repair", "Closed reduction percutaneous pinning"],
  "hook-of-hamate-fracture": ["Excision of hook fragment", "ORIF"],
  "fingertip-injury": ["Local flap coverage", "Skin graft", "Revision amputation", "Nail bed repair"],
  "tendon-laceration": ["Primary flexor tendon repair", "Primary extensor tendon repair", "Staged tendon reconstruction (chronic)"],
};

function surgicalOptionsFor(conditionId) {
  return SURGICAL_OPTIONS_BY_CONDITION[conditionId] || [];
}

// Complications tailored to the procedure type - matched against the
// procedure's own name text, so this applies correctly across all ~150
// individual procedure options above without needing a hand-written list
// per exact procedure name. Every procedure also gets the generic surgical
// risks below regardless of category.
const GENERIC_SURGICAL_COMPLICATIONS = ["Infection", "Bleeding", "Anaesthetic risk", "Scar sensitivity", "Persistent pain"];

const PROCEDURE_COMPLICATION_CATEGORIES = [
  { test: /arthroplasty|replacement|prosthetic|implant/i, items: ["Implant loosening or wear", "Periprosthetic fracture", "Dislocation or instability", "Need for revision surgery", "Deep vein thrombosis / pulmonary embolism"] },
  { test: /repair|reconstruction|reinsertion|tenodesis|ligament/i, items: ["Re-tear or failure of repair", "Stiffness", "Incomplete return of strength"] },
  { test: /release|decompress/i, items: ["Incomplete symptom relief", "Recurrent compression", "Nerve or vessel injury"] },
  { test: /fixation|\bORIF\b|pinning|plate|screw|nail/i, items: ["Nonunion or malunion", "Hardware irritation or need for removal", "Loss of fixation"] },
  { test: /fusion|arthrodesis/i, items: ["Nonunion", "Adjacent joint stress", "Loss of motion"] },
  { test: /trapeziectomy|excision/i, items: ["Subsidence / loss of length", "Residual weakness"] },
  { test: /transposition|transfer/i, items: ["Altered or incomplete function", "Recurrent symptoms at the new site"] },
  { test: /debridement|tenotomy/i, items: ["Incomplete pain relief", "Weakness"] },
  { test: /osteotomy/i, items: ["Nonunion or delayed union", "Malalignment"] },
  { test: /\bgraft\b/i, items: ["Graft failure or resorption", "Donor site morbidity"] },
  { test: /balloon|spacer/i, items: ["Device migration or deflation", "Limited durability of benefit"] },
  { test: /amputation/i, items: ["Neuroma formation", "Phantom or residual limb pain"] },
];

function complicationsForProcedure(procedureName) {
  const items = [...GENERIC_SURGICAL_COMPLICATIONS];
  PROCEDURE_COMPLICATION_CATEGORIES.forEach((cat) => {
    if (cat.test.test(procedureName)) items.push(...cat.items);
  });
  return [...new Set(items)];
}

// Patient-specific risk modifiers, derived only from what's already been
// documented for this patient in the encounter - never invented. Scans
// every checkbox field's selected values (regardless of the field's key
// name, which varies across templates - e.g. riskFactors, medHistory,
// relevantHistory) for known risk-modifying terms, so it works generically
// without needing to enumerate every field key across 56 templates.
const PATIENT_RISK_MODIFIER_RULES = [
  { test: /smoking/i, text: "Smoking \u2014 increased risk of delayed healing, infection, and higher re-tear/nonunion rate" },
  { test: /diabetes/i, text: "Diabetes \u2014 increased risk of infection and delayed or impaired healing" },
  { test: /rheumatoid|inflammatory/i, text: "Inflammatory arthritis \u2014 delayed rehabilitation and higher revision risk" },
];

function patientRiskModifiers(state) {
  const found = new Set();
  const modifiers = [];
  Object.values(state || {}).forEach((val) => {
    if (!Array.isArray(val)) return;
    val.forEach((item) => {
      if (typeof item !== "string") return;
      PATIENT_RISK_MODIFIER_RULES.forEach((rule) => {
        if (rule.test.test(item) && !found.has(rule.text)) {
          found.add(rule.text);
          modifiers.push(rule.text);
        }
      });
    });
  });
  const age = parseInt(state && state.age, 10);
  if (!isNaN(age) && age >= 65) modifiers.push("Older age / potentially reduced bone quality \u2014 increased risk of fixation failure, periprosthetic fracture, or slower healing");
  if (state && state.workDemand === "Heavy manual") modifiers.push("Heavy manual occupation \u2014 higher mechanical stress on the repair/reconstruction and return-to-work considerations");
  if (state && state.sport && state.sport.trim()) modifiers.push("Sporting activity \u2014 return-to-sport considerations and risk of re-injury with early return");
  return modifiers;
}

// Combines procedure-specific and patient-specific complications for
// whichever procedure(s) were actually selected, only producing text when
// the clinician has explicitly toggled that complications were discussed -
// mirrors the same never-assume-consent approach as the surgery-agreement
// and injection prompts.
function buildComplicationsSentence(procedures, state) {
  if (!procedures || !procedures.length) return null;
  const procComplications = new Set();
  procedures.forEach((p) => complicationsForProcedure(p).forEach((c) => procComplications.add(c)));
  const modifiers = patientRiskModifiers(state);
  const lines = [`Risks discussed included: ${humanizeList([...procComplications], { preserveCase: true })}.`];
  if (modifiers.length) lines.push(`Patient-specific factors increasing risk include: ${humanizeList(modifiers, { preserveCase: true })}.`);
  return lines.join(" ");
}

const SURGERY_KEYWORDS = /(surger|surgical|operat|reconstruct|arthroscop|debridement|excision|excise|fixation|osteotom|\brepair|\brelease\b|decompress|replacement|arthroplasty|\btransfer|\bgraft|pinning|\bORIF\b|open reduction|fusion|amputation|replant|neurolysis|tenolysis|synovectomy)/i;

// Gives the clinician a way to deviate from the Management Pathway's
// suggested step when it doesn't fit what they actually want to do for
// this patient - either picking a different, still-structured option from
// this generic list, or writing the plan out manually. Both combine with
// the pathway-suggested bullets in the note rather than replacing them.
const PATHWAY_ALT_OPTIONS = [
  "Continue conservative management as per pathway",
  "Trial of injection",
  "Physiotherapy",
  "Hand therapy",
  "Activity modification",
  "Splint or brace",
  "Discuss surgical options",
  "Further imaging or investigations",
  "Refer to another specialist",
  "Other",
];

// Walks the same trail PathwayFlow renders (start node -> answered
// questions -> reached terminal) for one set of answers, returning only the
// management content (info and terminal node text) - the decision points
// (question nodes) that got the clinician there are the reasoning trail,
// not something restated in the note.
// Given a schema, walks forward from a starting node through any
// consecutive "info" nodes (following .next) until reaching the first
// "question" or "terminal" node. Used so a pathway can start from the
// first actual decision point rather than repeating the initial
// framing/first-line management steps, when the patient has already been
// through that much (e.g. prior treatment already documented, or this is a
// follow-up visit by definition).
function firstDecisionNodeId(schema, fromId) {
  let id = fromId;
  let guard = 0;
  while (id && guard < 50) {
    const node = schema.nodes[id];
    if (!node || node.type !== "info" || !node.next) break;
    id = node.next;
    guard++;
  }
  return id;
}

// Many pathways open with a fixed "try this first" info step (e.g.
// education, activity modification, NSAIDs, physiotherapy) before the
// first real decision point. If the patient has already had prior
// treatment documented in History, forcing the clinician to walk through
// that same first-line step again doesn't reflect where this patient's
// care has actually reached - so this walks past any leading info nodes
// (following .next) to find the first question/terminal node, returning
// both that "effective start" id and the info nodes that were skipped, so
// the UI can still show them for context (as already-addressed) without
// requiring interaction.
function skipCompletedInfoSteps(schema, priorTreatmentGiven) {
  if (!priorTreatmentGiven || !schema) return { effectiveStart: schema ? schema.start : null, skipped: [] };
  const skipped = [];
  let currentId = schema.start;
  let guard = 0;
  while (currentId && guard < 50) {
    guard++;
    const node = schema.nodes[currentId];
    if (!node || node.type !== "info" || !node.next) break;
    skipped.push({ id: currentId, node });
    currentId = node.next;
  }
  return { effectiveStart: currentId || schema.start, skipped };
}

function walkPathwayTrail(schema, answers, startId) {
  const trail = [];
  let currentId = startId || schema.start;
  let guard = 0;
  while (currentId && guard < 50) {
    guard++;
    const node = schema.nodes[currentId];
    if (!node) break;
    trail.push({ id: currentId, node });
    if (node.type === "info") currentId = node.next;
    else if (node.type === "question") {
      const ans = answers[currentId];
      if (!ans) break;
      const branch = node.options.find((o) => o.label === ans);
      currentId = branch ? branch.next : null;
    } else break;
  }
  return trail;
}

// Turns a walked trail into bullet strings (without the bullet character
// itself): each node's chained steps ("A → B → C") become individual
// bullets in the order the pathway actually reached them, which in this
// stepped-care model is also the order of clinical priority (conservative
// measures first, escalation later). When the reached plan involves an
// operative step, a line documenting that risks, benefits, and
// complications were discussed and the patient agreed to proceed is
// appended automatically.
// Lets the UI (ConditionTemplate, FollowupConditionBlock) know whether the
// trail the clinician has currently walked reaches a surgical step, so it
// can show the "did the patient agree to surgery?" prompt only when it's
// actually relevant.
function pathwayTrailInvolvesSurgery(schema, answers) {
  if (!schema || !answers || !Object.keys(answers).length) return false;
  const trail = walkPathwayTrail(schema, answers);
  const stepTexts = trail.filter((t) => t.node.type === "info" || t.node.type === "terminal").map((t) => t.node.text);
  return SURGERY_KEYWORDS.test(stepTexts.join(" "));
}

const INJECTION_KEYWORDS_RE = /injection/i;

// Injection shows up two ways across this app: as a step the Management
// Pathway itself reaches (e.g. trigger finger's injection step), or as a
// clinician-picked "Trial of injection" alternative option. Either one
// means it's genuinely part of today's plan, so both are checked together
// - this is the single detection point every UI location below calls.
function planInvolvesInjection(schema, answers, altOptionsSelected) {
  if (schema && answers && Object.keys(answers).length) {
    const trail = walkPathwayTrail(schema, answers);
    const stepTexts = trail.filter((t) => t.node.type === "info" || t.node.type === "terminal").map((t) => t.node.text);
    if (INJECTION_KEYWORDS_RE.test(stepTexts.join(" "))) return true;
  }
  return (altOptionsSelected || []).includes("Trial of injection");
}

// Mirrors the surgery-agreement gate: never assumes the injection was
// actually given just because it's part of the plan. Only produces a
// sentence once the clinician has explicitly recorded whether the patient
// agreed, and reports timing accurately - "given today" only when it
// genuinely was, "to be scheduled" when it's planned for later.
function buildInjectionSentence(detail) {
  if (!detail || !detail.agreement) return null;
  if (detail.agreement === "Not agreed") return "The patient was not keen for the injection at this time.";
  if (detail.timing === "Scheduled for a later date") {
    const when = detail.scheduledDate && detail.scheduledDate.trim() ? detail.scheduledDate.trim() : "a later date";
    return `The patient agreed to the injection; this will be scheduled for ${when}.`;
  }
  return "The patient agreed to the injection. Injection was given safely using sterile technique. Risks, benefits and alternatives were discussed with the patient prior to the injection.";
}

// When the reached plan involves surgery, the note no longer assumes
// consent by default - it reports whichever the clinician actually
// recorded: "Agreed" documents risks/benefits/complications/alternatives
// discussed and consent given; "Not agreed" records the alternate outcome
// plainly; leaving it unanswered omits the sentence entirely rather than
// guessing.
function trailToBullets(trail, surgeryAgreement, surgicalDiscussion) {
  const stepTexts = trail.filter((t) => t.node.type === "info" || t.node.type === "terminal").map((t) => t.node.text);
  if (!stepTexts.length) return [];

  const bullets = [];
  stepTexts.forEach((text) => {
    text
      .split("\u2192")
      .map((s) => s.trim())
      .filter(Boolean)
      .forEach((s) => bullets.push(/^diagnosis$/i.test(s) ? "The probable diagnosis was discussed with the patient." : s));
  });
  if (!bullets.length) return [];

  const combinedText = stepTexts.join(" ");
  if (SURGERY_KEYWORDS.test(combinedText)) {
    if (surgeryAgreement === "Agreed") {
      const procedures = ((surgicalDiscussion && surgicalDiscussion.selected) || []).filter((p) => p !== "Other");
      if (surgicalDiscussion && (surgicalDiscussion.selected || []).includes("Other") && surgicalDiscussion.otherText && surgicalDiscussion.otherText.trim()) {
        procedures.push(surgicalDiscussion.otherText.trim());
      }
      const procedureClause = procedures.length ? `proceed with ${humanizeList(procedures, { preserveCase: true })}` : "proceed with the recommended surgical management";
      bullets.push(
        `The risks and benefits of surgery, including common complications associated with the proposed procedure, and alternative treatment options, were discussed with the patient, who agreed to ${procedureClause}.`
      );
    } else if (surgeryAgreement === "Not agreed") {
      bullets.push("The patient was not keen for surgery at this time.");
    }
  }
  return bullets;
}

function proceduresFromDiscussion(discussion) {
  const procedures = ((discussion && discussion.selected) || []).filter((p) => p !== "Other");
  if (discussion && (discussion.selected || []).includes("Other") && discussion.otherText && discussion.otherText.trim()) {
    procedures.push(discussion.otherText.trim());
  }
  return procedures;
}

function buildManagementPlan(condition, state) {
  if (!condition.pathway) return null;

  // Trigger finger: each affected digit is walked through the Management
  // Pathway independently, since digits can genuinely differ in severity
  // and end up with different recommendations (one settles with an
  // injection, another needs release).
  if (condition.id === "trigger-finger") {
    const priorTx = (state.prevTreatment || []).length > 0;
    const parts = [];
    (state.affectedDigits || []).forEach((digit) => {
      const digitAnswers = state.pathwayAnswersByDigit?.[digit] || {};
      const digitAlt = state.pathwayAltByDigit?.[digit] || {};
      const digitDiscussion = state.surgicalDiscussionByDigit?.[digit];
      const bullets = [];
      if (Object.keys(digitAnswers).length) {
        const { effectiveStart } = skipCompletedInfoSteps(condition.pathway, priorTx);
        bullets.push(...trailToBullets(walkPathwayTrail(condition.pathway, digitAnswers, effectiveStart), state.pathwaySurgeryAgreementByDigit?.[digit], digitDiscussion));
      }
      const digitAltPlan = (digitAlt.options || []).filter((p) => p !== "Other");
      if ((digitAlt.options || []).includes("Other") && digitAlt.optionsOther && digitAlt.optionsOther.trim()) digitAltPlan.push(digitAlt.optionsOther.trim());
      if (digitAlt.manualPlan && digitAlt.manualPlan.trim()) digitAltPlan.push(digitAlt.manualPlan.trim());
      bullets.push(...digitAltPlan);
      const digitInjectionSentence = buildInjectionSentence(state.injectionDetailByDigit?.[digit]);
      if (digitInjectionSentence) bullets.push(digitInjectionSentence);
      if (digitDiscussion && digitDiscussion.complicationsDiscussed) {
        const compSentence = buildComplicationsSentence(proceduresFromDiscussion(digitDiscussion), state);
        if (compSentence) bullets.push(compSentence);
      }
      if (bullets.length) parts.push(`${digit}:\n${bullets.map((b) => `\u2022 ${b}`).join("\n")}`);
    });
    return parts.length ? parts.join("\n\n") : null;
  }

  const altPlan = (state.pathwayAltOptions || []).filter((p) => p !== "Other");
  if ((state.pathwayAltOptions || []).includes("Other") && state.pathwayAltOptionsOther && state.pathwayAltOptionsOther.trim()) altPlan.push(state.pathwayAltOptionsOther.trim());
  if (state.pathwayManualPlan && state.pathwayManualPlan.trim()) altPlan.push(state.pathwayManualPlan.trim());

  if (state.side === "Bilateral") {
    const rightAnswers = state.pathwayAnswersRight || {};
    const leftAnswers = state.pathwayAnswersLeft || {};
    const rightPriorTx = ((state.limbData?.right?.prevTreatment) || []).length > 0;
    const leftPriorTx = ((state.limbData?.left?.prevTreatment) || []).length > 0;
    const parts = [];
    if (Object.keys(rightAnswers).length) {
      const { effectiveStart } = skipCompletedInfoSteps(condition.pathway, rightPriorTx);
      const bullets = trailToBullets(walkPathwayTrail(condition.pathway, rightAnswers, effectiveStart), state.pathwaySurgeryAgreementRight, state.surgicalDiscussionRight);
      const rightInjectionSentence = buildInjectionSentence(state.injectionDetailRight);
      if (rightInjectionSentence) bullets.push(rightInjectionSentence);
      if (state.surgicalDiscussionRight && state.surgicalDiscussionRight.complicationsDiscussed) {
        const compSentence = buildComplicationsSentence(proceduresFromDiscussion(state.surgicalDiscussionRight), state);
        if (compSentence) bullets.push(compSentence);
      }
      if (bullets.length) parts.push(`Right side:\n${bullets.map((b) => `\u2022 ${b}`).join("\n")}`);
    }
    if (Object.keys(leftAnswers).length) {
      const { effectiveStart } = skipCompletedInfoSteps(condition.pathway, leftPriorTx);
      const bullets = trailToBullets(walkPathwayTrail(condition.pathway, leftAnswers, effectiveStart), state.pathwaySurgeryAgreementLeft, state.surgicalDiscussionLeft);
      const leftInjectionSentence = buildInjectionSentence(state.injectionDetailLeft);
      if (leftInjectionSentence) bullets.push(leftInjectionSentence);
      if (state.surgicalDiscussionLeft && state.surgicalDiscussionLeft.complicationsDiscussed) {
        const compSentence = buildComplicationsSentence(proceduresFromDiscussion(state.surgicalDiscussionLeft), state);
        if (compSentence) bullets.push(compSentence);
      }
      if (bullets.length) parts.push(`Left side:\n${bullets.map((b) => `\u2022 ${b}`).join("\n")}`);
    }
    // Alternative/manual plan entries are shared regardless of laterality,
    // consistent with how Typical Patient content is shared elsewhere.
    if (altPlan.length) parts.push(`Alternative/additional plan:\n${altPlan.map((b) => `\u2022 ${b}`).join("\n")}`);
    return parts.length ? parts.join("\n\n") : null;
  }

  const answers = state.pathwayAnswers || {};
  const priorTx = (state.prevTreatment || []).length > 0;
  const { effectiveStart } = skipCompletedInfoSteps(condition.pathway, priorTx);
  const bullets = Object.keys(answers).length ? trailToBullets(walkPathwayTrail(condition.pathway, answers, effectiveStart), state.pathwaySurgeryAgreement, state.surgicalDiscussion) : [];
  bullets.push(...altPlan);
  const injectionSentence = buildInjectionSentence(state.injectionDetail);
  if (injectionSentence) bullets.push(injectionSentence);
  if (state.surgicalDiscussion && state.surgicalDiscussion.complicationsDiscussed) {
    const compSentence = buildComplicationsSentence(proceduresFromDiscussion(state.surgicalDiscussion), state);
    if (compSentence) bullets.push(compSentence);
  }
  if (!bullets.length) return null;
  return bullets.map((b) => `\u2022 ${b}`).join("\n");
}

// The follow-up interval/objectives are condition-level standard-of-care
// content (a static table, not tied to any state field), so this section is
// derived from the condition's own nearest review row rather than from
// clinician-entered data — every note should still end with a review plan.
// True once the patient has both agreed to surgery and a specific plan has
// been chosen or written (not just the bare agreement) - at that point a
// routine follow-up interval no longer makes sense as "the plan"; what's
// actually next is scheduling the operation. Checks every context this can
// happen in: the main pathway (unilateral and bilateral, per side) and
// trigger finger's per-digit pathway.
function patientScheduledForSurgery(state) {
  const hasPlan = (discussion) => ((discussion && discussion.selected) || []).length > 0;
  if (state.pathwaySurgeryAgreement === "Agreed" && hasPlan(state.surgicalDiscussion)) return true;
  if (state.pathwaySurgeryAgreementRight === "Agreed" && hasPlan(state.surgicalDiscussionRight)) return true;
  if (state.pathwaySurgeryAgreementLeft === "Agreed" && hasPlan(state.surgicalDiscussionLeft)) return true;
  if (state.pathwaySurgeryAgreementByDigit) {
    for (const digit of Object.keys(state.pathwaySurgeryAgreementByDigit)) {
      if (state.pathwaySurgeryAgreementByDigit[digit] === "Agreed" && hasPlan(state.surgicalDiscussionByDigit?.[digit])) return true;
    }
  }
  return false;
}

function buildReviewPlan(condition, state) {
  const followup = condition.sections.find((s) => s.id === "followup");
  let reviewSentence = null;
  if (patientScheduledForSurgery(state)) {
    reviewSentence = "The patient will be scheduled for surgery.";
  } else if (followup) {
    const tableField = (followup.fields || []).find((f) => f.type === "table");
    const selectedInterval = state.followUpInterval === "Other" ? state.followUpIntervalOther : state.followUpInterval;
    if (selectedInterval && selectedInterval.trim()) {
      const matchedRow = tableField && tableField.rows && tableField.rows.find((r) => r.left === selectedInterval);
      reviewSentence = matchedRow
        ? `The patient will be reviewed at ${selectedInterval}, when ${lowerFirst(matchedRow.right)} will be assessed.`
        : `The patient will be reviewed at ${selectedInterval}.`;
    }
    // Deliberately no fallback here. Previously this defaulted to the
    // condition's first standard-follow-up row when no interval had been
    // selected, which meant the note asserted a specific follow-up
    // commitment ("will be reviewed at 6-8 weeks") that the clinician had
    // never actually chosen. A generated clinical note must not state
    // decisions that weren't made, so when no interval is selected the
    // Review Plan section is simply omitted.

    const followUpReasons = (state.followUpReason || []).filter((r) => r !== "Other");
    if ((state.followUpReason || []).includes("Other") && state.followUpReasonOther && state.followUpReasonOther.trim()) followUpReasons.push(state.followUpReasonOther.trim());
    if (followUpReasons.length && reviewSentence) {
      reviewSentence += ` The reason for follow-up is ${lowerFirst(humanizeList(followUpReasons))}.`;
    }
  }
  // Any genuinely entered follow-up/healing-dashboard data (as opposed to
  // the static pearls/predictors/table reference content in this section)
  // is folded in here as additional findings at this visit, since it
  // represents review-stage data rather than fitting any of the other
  // eight parts of the note.
  const outcomes = condition.sections.find((s) => s.id === "outcomes");
  let addendum = null;
  if (outcomes) {
    const clauses = [];
    resolveFields(outcomes.fields, state).forEach((f) => {
      const c = fieldClause(f, state);
      if (c) clauses.push(c);
    });
    if (clauses.length) addendum = `At this visit, ${joinClausesLower(clauses)}`;
  }
  if (reviewSentence && addendum) return `${reviewSentence} ${addendum}`;
  return reviewSentence || addendum || null;
}

// Assembles the fixed nine-part note structure for one condition, returning
// only the parts that have data. Shared by both the single-condition note
// and the combined multi-condition note below.
function buildProseNote(condition, state) {
  const parts = [];
  const push = (heading, text) => {
    if (text) parts.push({ heading, text });
  };
  push("Patient", buildDemographics(condition, state));
  push("History", buildHistory(condition, state));
  push("Examination", buildExamination(condition, state));
  push("Imaging", buildImaging(condition, state));
  push("Red Flags", buildRedFlagsExcluded(condition, state));
  push("Differential Diagnosis", buildDifferential(condition, state));
  push("Impression", buildImpression(condition, state));
  push("Management Plan", buildManagementPlan(condition, state));
  push("Review Plan", buildReviewPlan(condition, state));
  return parts;
}

// Returns the urgent-tier flags actually checked as present for this
// condition, e.g. for a top-of-note safety banner. Kept separate from
// buildRedFlagsExcluded, which documents *all* flags (present + excluded)
// as part of the fixed nine-part body.
function getPresentUrgentFlags(condition, state) {
  const urgentChecked = state.urgentFlagsChecked || [];
  return (condition.urgentFlags || []).filter((_, i) => urgentChecked.includes(i));
}

function buildNote(condition, state) {
  const parts = buildProseNote(condition, state);
  const presentUrgent = getPresentUrgentFlags(condition, state);
  const lines = [`CLINIC NOTE \u2014 ${condition.name}`, ""];
  // A senior clinician scanning this note needs to see anything
  // safety-critical before anything else, regardless of where in the
  // documentation it was captured \u2014 so urgent flags checked as present get
  // a banner above the fixed section structure, in addition to still
  // appearing in the Red Flags section below in full context.
  if (presentUrgent.length) {
    lines.push(`\u26a0 URGENT \u2014 REQUIRES IMMEDIATE ATTENTION: ${presentUrgent.map((f) => f.text).join("; ")}.`);
    lines.push("");
  }
  if (!parts.length) {
    lines.push("No findings have been documented yet for this condition.");
  } else {
    parts.forEach((p) => {
      lines.push(p.heading.toUpperCase());
      lines.push(p.text);
      lines.push("");
    });
  }
  lines.push("---");
  lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
  return lines.join("\n");
}

// Combines every condition active in the patient session into one note,
// each under its own heading, for consultations with more than one working
// diagnosis (e.g. Rotator Cuff Disease + AC Joint Disorders).
function buildCombinedNote(session) {
  const items = session.order.map((id) => findConditionById(id)).filter(Boolean);
  const lines = ["COMBINED CLINIC NOTE", `${items.length} condition${items.length === 1 ? "" : "s"} documented this session`, ""];

  // Session-wide safety banner, same rationale as the single-condition note:
  // a senior clinician needs to see anything urgent across every active
  // condition before reading the detail of any one of them.
  const urgentBySeen = items
    .map((condition) => ({ condition, present: getPresentUrgentFlags(condition, session.statesByConditionId[condition.id] || {}) }))
    .filter((x) => x.present.length);
  if (urgentBySeen.length) {
    lines.push("\u26a0 URGENT \u2014 REQUIRES IMMEDIATE ATTENTION:");
    urgentBySeen.forEach(({ condition, present }) => {
      lines.push(`  \u2022 ${condition.name}: ${present.map((f) => f.text).join("; ")}.`);
    });
    lines.push("");
  }

  // The first diagnosis added to the session is treated as primary and
  // every other active diagnosis as secondary - this is the same ordering
  // already used for the "N diagnoses reviewed" chips elsewhere, so it
  // stays consistent with how the session is actually built up.
  const withStates = items.map((condition) => ({ condition, state: session.statesByConditionId[condition.id] || {} }));
  const labelFor = (idx) => (idx === 0 ? "Primary" : "Secondary");

  // Guard against an empty session: previously this emitted the section
  // headings below with nothing under them, producing a note that looked
  // broken rather than simply reporting that nothing was documented.
  if (!withStates.length) {
    lines.push("No conditions were documented in this session.");
    lines.push("");
    lines.push("---");
    lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
    return lines.join("\n");
  }

  lines.push("CONDITIONS ASSESSED THIS SESSION");
  lines.push(`Primary diagnosis: ${withStates[0].condition.name}`);
  const secondaries = withStates.slice(1);
  if (secondaries.length) {
    lines.push(`Secondary diagnos${secondaries.length === 1 ? "is" : "es"}: ${secondaries.map((s) => s.condition.name).join(", ")}`);
  }
  lines.push("");

  lines.push("RED FLAGS");
  withStates.forEach(({ condition, state }, idx) => {
    const text = buildRedFlagsExcluded(condition, state) || "Red flags not yet reviewed for this diagnosis.";
    lines.push(`${condition.name} (${labelFor(idx)}): ${text}`);
  });
  lines.push("");

  // Patient demographics are the same patient regardless of how many
  // diagnoses are active in this session, so they're stated once - using
  // whichever condition has them documented first, rather than repeating
  // (and risking re-typing inconsistencies of) the same facts per diagnosis.
  let demographicsText = null;
  for (const { condition, state } of withStates) {
    const text = buildDemographics(condition, state);
    if (text) {
      demographicsText = text;
      break;
    }
  }
  if (demographicsText) {
    lines.push("PATIENT");
    lines.push(demographicsText);
    lines.push("");
  }

  const pushPerDiagnosisSection = (heading, builder) => {
    const entries = withStates.map(({ condition, state }, idx) => ({ condition, idx, text: builder(condition, state) })).filter((e) => e.text);
    if (!entries.length) return;
    lines.push(heading);
    entries.forEach(({ condition, idx, text }) => {
      lines.push(`${condition.name} (${labelFor(idx)})`);
      lines.push(text);
      lines.push("");
    });
  };

  pushPerDiagnosisSection("HISTORY", buildHistory);
  pushPerDiagnosisSection("EXAMINATION", buildExamination);
  pushPerDiagnosisSection("IMAGING", buildImaging);
  pushPerDiagnosisSection("DIFFERENTIAL DIAGNOSIS", buildDifferential);

  // Impression is combined into a single paragraph covering every
  // diagnosis reached this session, rather than repeated as separate
  // per-condition blocks, since it's meant to read as one overall clinical
  // picture for the patient.
  const impressionParts = withStates
    .map(({ condition, state }, idx) => {
      const text = buildImpression(condition, state);
      if (!text) return null;
      const clause = text.replace(/^Clinical impression:\s*/i, "").trim().replace(/\.$/, "");
      return `${condition.name} (${labelFor(idx).toLowerCase()}) \u2014 ${clause}`;
    })
    .filter(Boolean);
  if (impressionParts.length) {
    lines.push("IMPRESSION");
    lines.push(`Following assessment in this session, the clinical impression is as follows: ${impressionParts.join("; ")}.`);
    lines.push("");
  }

  // Management and review plans stay paired per diagnosis, since a plan
  // and its follow-up interval are only meaningful read together.
  withStates.forEach(({ condition, state }, idx) => {
    const mgmt = buildManagementPlan(condition, state);
    const review = buildReviewPlan(condition, state);
    if (!mgmt && !review) return;
    lines.push(`MANAGEMENT & REVIEW PLAN \u2014 ${condition.name} (${labelFor(idx)})`);
    if (mgmt) {
      lines.push("Management Plan:");
      lines.push(mgmt);
      lines.push("");
    }
    if (review) {
      lines.push("Review Plan:");
      lines.push(review);
      lines.push("");
    }
  });

  lines.push("---");
  lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
  return lines.join("\n");
}

// Generic options for the Follow-up Visit workflow. Deliberately not
// condition-specific (unlike the initial-encounter templates) since a
// follow-up visit's structure - why the patient is back, what was tried,
// how it went, what's next - is the same shape regardless of diagnosis;
// what differs per diagnosis is the actual "new plan" step, which reuses
// that condition's own Management Pathway rather than a generic list.
const FOLLOWUP_REASON_OPTIONS = ["Scheduled review", "Persistent or worsening symptoms", "New symptoms", "Post-injection review", "Post-operative review", "Patient-initiated concern", "Other"];
const FOLLOWUP_TREATMENT_OPTIONS = ["Education / activity modification", "Physiotherapy", "Hand therapy", "Splint or brace", "Corticosteroid injection", "Medication (NSAIDs/analgesia)", "Surgery", "Other"];
const FOLLOWUP_OUTCOME_OPTIONS = ["Resolved", "Improved", "Unchanged", "Worse"];

// Reason for the *next* review, distinct from FOLLOWUP_REASON_OPTIONS above
// (which captures why today's visit happened). Only relevant once a next
// review interval has actually been selected, and not shown at all when
// the interval is "Final" - a discharge doesn't need a reason for a future
// visit that isn't happening.
const FOLLOWUP_NEXT_REVIEW_REASON_OPTIONS = ["Routine review of treatment progress", "Reassess symptoms and function", "Review investigation results", "Assess response to injection/treatment", "Monitor for progression", "Pre-operative planning", "Other"];

// Gives the clinician a way out of the pathway-suggested plan when it
// doesn't fit what they actually want to do at this visit \u2014 either picking
// a different, still-structured plan from this generic list, or writing the
// plan out manually. All three sources (pathway, this checklist, manual
// text) combine into one New Plan of Treatment section rather than
// requiring an either/or choice, since a real plan is often a mix (e.g. the
// pathway's suggested step plus a manual note about something specific to
// this patient).
const FOLLOWUP_PLAN_OPTIONS = [
  "Continue current management as planned",
  "Progress treatment (e.g. advance rehabilitation, increase activity)",
  "Modify or step down treatment",
  "Trial of injection",
  "Refer for surgical opinion",
  "Refer to physiotherapy",
  "Refer to hand therapy",
  "Further imaging or investigations",
  "Discharge from follow-up",
  "Continue routine follow-up",
  "Other",
];

// Follow-up state lives in its own namespaced bucket (state.followup) inside
// the same per-condition session state used for initial encounters, so a
// condition can carry both an initial workup and follow-up documentation in
// the same session without either overwriting the other's fields (e.g. both
// use a pathway walk, but as separate answer sets).
function buildFollowupNoteParts(condition, fuState, fullState) {
  const parts = [];

  const reasons = (fuState.reason || []).filter((r) => r !== "Other");
  if ((fuState.reason || []).includes("Other") && fuState.reasonOther && fuState.reasonOther.trim()) reasons.push(fuState.reasonOther.trim());
  if (reasons.length) parts.push({ heading: "Reason for Review", text: `The patient was reviewed today for ${lowerFirst(humanizeList(reasons))}.` });

  const treatments = (fuState.treatmentOffered || []).filter((t) => t !== "Other");
  if ((fuState.treatmentOffered || []).includes("Other") && fuState.treatmentOfferedOther && fuState.treatmentOfferedOther.trim()) treatments.push(fuState.treatmentOfferedOther.trim());
  if (treatments.length) parts.push({ heading: "Treatment Since Last Visit", text: `Since the last visit, the patient received ${lowerFirst(humanizeList(treatments))}.` });

  if (fuState.outcome) {
    let t = `Response to treatment has been ${fuState.outcome.toLowerCase()}`;
    if (fuState.outcomeNotes && fuState.outcomeNotes.trim()) t += `; ${lowerFirst(fuState.outcomeNotes.trim())}`;
    parts.push({ heading: "Outcome of Treatment", text: `${t}.` });
  }

  const planBullets = [];
  if (condition.pathway && fuState.pathwayAnswers && Object.keys(fuState.pathwayAnswers).length) {
    const priorTx = (fuState.treatmentOffered || []).length > 0;
    const { effectiveStart } = skipCompletedInfoSteps(condition.pathway, priorTx);
    planBullets.push(...trailToBullets(walkPathwayTrail(condition.pathway, fuState.pathwayAnswers, effectiveStart), fuState.pathwaySurgeryAgreement, fuState.surgicalDiscussion));
  }
  const altPlan = (fuState.planOptions || []).filter((p) => p !== "Other");
  if ((fuState.planOptions || []).includes("Other") && fuState.planOptionsOther && fuState.planOptionsOther.trim()) altPlan.push(fuState.planOptionsOther.trim());
  planBullets.push(...altPlan);
  if (fuState.planManualText && fuState.planManualText.trim()) planBullets.push(fuState.planManualText.trim());
  const followupInjectionSentence = buildInjectionSentence(fuState.injectionDetail);
  if (followupInjectionSentence) planBullets.push(followupInjectionSentence);
  if (fuState.surgicalDiscussion && fuState.surgicalDiscussion.complicationsDiscussed) {
    const compSentence = buildComplicationsSentence(proceduresFromDiscussion(fuState.surgicalDiscussion), fullState || fuState);
    if (compSentence) planBullets.push(compSentence);
  }
  if (planBullets.length) parts.push({ heading: "New Plan of Treatment", text: planBullets.map((b) => `\u2022 ${b}`).join("\n") });

  const selectedInterval = fuState.followUpInterval === "Other" ? fuState.followUpIntervalOther : fuState.followUpInterval;
  if (patientScheduledForSurgery(fuState)) {
    parts.push({ heading: "Review Plan", text: "The patient will be scheduled for surgery." });
  } else if (fuState.followUpInterval === "Final") {
    parts.push({ heading: "Review Plan", text: "This is the final visit for the patient. They can be discharged from the clinic." });
  } else if (selectedInterval && selectedInterval.trim()) {
    let text = `The patient will be reviewed at ${selectedInterval}.`;
    const nextReasons = (fuState.nextReviewReason || []).filter((r) => r !== "Other");
    if ((fuState.nextReviewReason || []).includes("Other") && fuState.nextReviewReasonOther && fuState.nextReviewReasonOther.trim()) nextReasons.push(fuState.nextReviewReasonOther.trim());
    if (nextReasons.length) text += ` The reason for follow-up is ${lowerFirst(humanizeList(nextReasons))}.`;
    parts.push({ heading: "Review Plan", text });
  }

  return parts;
}

function buildFollowupNote(condition, state) {
  const fuState = state.followup || {};
  const parts = buildFollowupNoteParts(condition, fuState, state);
  const lines = [`FOLLOW-UP VISIT NOTE \u2014 ${condition.name}`, ""];
  if (!parts.length) {
    lines.push("No follow-up findings have been documented yet for this condition.");
  } else {
    parts.forEach((p) => {
      lines.push(p.heading.toUpperCase());
      lines.push(p.text);
      lines.push("");
    });
  }
  lines.push("---");
  lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
  return lines.join("\n");
}

function buildCombinedFollowupNote(session, conditionIds) {
  const items = conditionIds.map((id) => findConditionById(id)).filter(Boolean);
  const lines = ["FOLLOW-UP VISIT NOTE", `${items.length} diagnos${items.length === 1 ? "is" : "es"} reviewed this visit`, ""];
  items.forEach((condition) => {
    const state = session.statesByConditionId[condition.id] || {};
    const fuState = state.followup || {};
    const parts = buildFollowupNoteParts(condition, fuState, state);
    lines.push(`\u2550\u2550 ${condition.name.toUpperCase()} \u2550\u2550`, "");
    if (!parts.length) {
      lines.push("(No follow-up findings recorded for this diagnosis.)", "");
    } else {
      parts.forEach((p) => {
        lines.push(p.heading.toUpperCase());
        lines.push(p.text);
        lines.push("");
      });
    }
  });
  lines.push("---");
  lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
  return lines.join("\n");
}

// Generic options for the Post-operative Follow-up workflow. Complications
// deliberately includes "None noted" as an explicit, mutually-exclusive
// option (handled in PostopConditionBlock's onChange) rather than leaving
// "nothing selected" to silently mean "no complications" \u2014 an unreviewed
// field and a reviewed-and-clear field should never look the same in the
// note.
const POSTOP_REASON_OPTIONS = ["Scheduled post-operative review", "Wound check", "Suture removal", "Pin removal", "Cast removal", "Patient-reported concern", "Return to work/sport assessment", "Complication assessment", "Other"];

// Reason for the *next* review, distinct from POSTOP_REASON_OPTIONS above
// (which captures why today's visit happened). Only relevant once a next
// review interval has actually been selected, and not shown at all when
// the interval is "Final" - a discharge doesn't need a reason for a future
// visit that isn't happening.
const POSTOP_NEXT_REVIEW_REASON_OPTIONS = ["Routine post-operative review", "Wound/suture check", "Assess healing progress", "Monitor for complications", "Progress rehabilitation review", "Pre-discharge assessment", "Other"];
const POSTOP_WOUND_OPTIONS = ["Healing well", "Fully healed", "Delayed healing", "Dehiscence", "Signs of infection"];
const POSTOP_PROGRESS_OPTIONS = ["As expected for stage", "Ahead of expected progress", "Behind expected progress"];
const POSTOP_COMPLICATION_OPTIONS = ["None noted", "Wound infection", "Wound dehiscence", "Delayed healing", "Stiffness", "Neurovascular deficit", "DVT/PE", "Hardware-related pain", "Loss of fixation/reduction", "Recurrence", "Other"];

// A first-presentation patient's Management Pathway assumes the diagnostic
// workup hasn't happened yet (conservative-vs-surgical, staging, etc.),
// which is no longer the relevant decision once surgery has already been
// done \u2014 so the post-operative follow-up plan uses its own generic option
// set instead, applicable across every post-op follow-up regardless of
// which procedure was performed. Multi-select, since a real post-op plan
// often combines more than one of these (e.g. progress rehab + continue
// routine follow-up).
const POSTOP_PLAN_OPTIONS = [
  "Continue current rehabilitation protocol",
  "Progress rehabilitation / advance loading",
  "Modify or restrict rehabilitation",
  "Continue immobilization (splint/cast/sling)",
  "Wean from immobilization",
  "Trial of injection",
  "Refer to physiotherapy",
  "Refer to hand therapy",
  "Further imaging or investigations",
  "Treat complication (e.g. wound care, antibiotics)",
  "Discuss further surgical intervention / revision",
  "Discharge from follow-up",
  "Continue routine follow-up",
  "Other",
];

// "Time since surgery" is derived from the surgery date rather than asked
// as a separate field, since asking a clinician to compute and enter that
// themselves is redundant once the date is already known.
function timeSinceSurgery(dateStr) {
  if (!dateStr) return null;
  const surgDate = new Date(dateStr + "T00:00:00");
  if (isNaN(surgDate.getTime())) return null;
  const days = Math.round((Date.now() - surgDate.getTime()) / (1000 * 60 * 60 * 24));
  if (days < 0) return "date is in the future";
  if (days === 0) return "day of surgery";
  if (days < 14) return `${days} day${days === 1 ? "" : "s"}`;
  if (days < 90) return `${Math.round(days / 7)} week${Math.round(days / 7) === 1 ? "" : "s"}`;
  const months = Math.round(days / 30.44);
  return `${months} month${months === 1 ? "" : "s"}`;
}

function buildPostopNoteParts(condition, poState) {
  const parts = [];

  if (poState.procedureName && poState.procedureName.trim()) {
    const dateText = poState.surgeryDate ? ` on ${poState.surgeryDate}` : "";
    const sinceText = poState.surgeryDate ? timeSinceSurgery(poState.surgeryDate) : null;
    const sinceClause = sinceText ? ` (${sinceText} since surgery)` : "";
    parts.push({ heading: "Procedure", text: `The patient underwent ${poState.procedureName.trim()}${dateText}${sinceClause}.` });
  }

  const reasons = (poState.reason || []).filter((r) => r !== "Other");
  if ((poState.reason || []).includes("Other") && poState.reasonOther && poState.reasonOther.trim()) reasons.push(poState.reasonOther.trim());
  if (reasons.length) parts.push({ heading: "Reason for Review", text: `The patient was reviewed today for ${lowerFirst(humanizeList(reasons))}.` });

  const statusClauses = [];
  if (poState.woundStatus) statusClauses.push(`the wound was ${lowerFirst(poState.woundStatus)}`);
  if (poState.vas != null) statusClauses.push(`pain was ${poState.vas}/10`);
  if (poState.functionalProgress) statusClauses.push(`functional progress was ${lowerFirst(poState.functionalProgress)}`);
  if (poState.statusNotes && poState.statusNotes.trim()) statusClauses.push(poState.statusNotes.trim());
  if (statusClauses.length) parts.push({ heading: "Current Status", text: `${statusClauses.join("; ")}.`.replace(/^./, (c) => c.toUpperCase()) });

  const complications = (poState.complications || []).filter((c) => c !== "None noted" && c !== "Other");
  if ((poState.complications || []).includes("Other") && poState.complicationsOther && poState.complicationsOther.trim()) complications.push(poState.complicationsOther.trim());
  if (complications.length) {
    parts.push({ heading: "Complications", text: `The following complications were noted and require attention: ${humanizeList(complications)}.` });
  } else if ((poState.complications || []).includes("None noted")) {
    parts.push({ heading: "Complications", text: "No complications were noted." });
  }

  const plan = (poState.planOptions || []).filter((p) => p !== "Other");
  if ((poState.planOptions || []).includes("Other") && poState.planOptionsOther && poState.planOptionsOther.trim()) plan.push(poState.planOptionsOther.trim());
  const postopInjectionSentence = buildInjectionSentence(poState.injectionDetail);
  if (postopInjectionSentence) plan.push(postopInjectionSentence);
  if (plan.length) parts.push({ heading: "Follow-up Plan", text: plan.map((p) => `\u2022 ${p}`).join("\n") });

  const selectedInterval = poState.followUpInterval === "Other" ? poState.followUpIntervalOther : poState.followUpInterval;
  if (poState.followUpInterval === "Final") {
    parts.push({ heading: "Next Review", text: "This is the final visit for the patient. They can be discharged from the clinic." });
  } else if (selectedInterval && selectedInterval.trim()) {
    let text = `The patient will be reviewed at ${selectedInterval}.`;
    const nextReasons = (poState.nextReviewReason || []).filter((r) => r !== "Other");
    if ((poState.nextReviewReason || []).includes("Other") && poState.nextReviewReasonOther && poState.nextReviewReasonOther.trim()) nextReasons.push(poState.nextReviewReasonOther.trim());
    if (nextReasons.length) text += ` The reason for follow-up is ${lowerFirst(humanizeList(nextReasons))}.`;
    parts.push({ heading: "Next Review", text });
  }

  return parts;
}

function buildCombinedPostopNote(session, conditionIds) {
  const items = conditionIds.map((id) => findConditionById(id)).filter(Boolean);
  const lines = ["POST-OPERATIVE FOLLOW-UP NOTE", `${items.length} procedure${items.length === 1 ? "" : "s"} reviewed this visit`, ""];
  items.forEach((condition) => {
    const state = session.statesByConditionId[condition.id] || {};
    const poState = state.postop || {};
    const parts = buildPostopNoteParts(condition, poState);
    lines.push(`\u2550\u2550 ${condition.name.toUpperCase()} \u2550\u2550`, "");
    if (!parts.length) {
      lines.push("(No post-operative findings recorded for this diagnosis.)", "");
    } else {
      parts.forEach((p) => {
        lines.push(p.heading.toUpperCase());
        lines.push(p.text);
        lines.push("");
      });
    }
  });
  lines.push("---");
  lines.push("Generated with UpperTrack. For clinician review; not a diagnostic or treatment recommendation.");
  return lines.join("\n");
}

function sectionHasContent(section, state, conditionId) {
  const bilateral = state.side === "Bilateral";
  const isPerDigit = conditionId === "trigger-finger";
  if (section.id === "pathway") {
    if (isPerDigit) return Object.values(state.pathwayAnswersByDigit || {}).some((a) => Object.keys(a || {}).length > 0);
    if (bilateral) return Object.keys(state.pathwayAnswersRight || {}).length > 0 || Object.keys(state.pathwayAnswersLeft || {}).length > 0;
    return Object.keys(state.pathwayAnswers || {}).length > 0;
  }
  if (isPerDigit && section.id === "exam") {
    const digitSpecificKeys = new Set(["palpation", "activeFlexion", "activeExtension", "passiveMotion", "compositeFist", "tendonGliding", "triggerSeverity"]);
    const sharedFields = section.fields.filter((f) => !digitSpecificKeys.has(f.key));
    const perDigitFields = section.fields.filter((f) => digitSpecificKeys.has(f.key));
    const sharedFilled = sharedFields.some((f) => isFilled(f, state));
    const digitFilled = Object.values(state.digitData || {}).some((d) => perDigitFields.some((f) => isFilled(f, d || {})));
    return sharedFilled || digitFilled;
  }
  if (bilateral && (section.id === "history" || section.id === "exam" || section.id === "imaging" || section.id === "diagnosis")) {
    const sharedFields = section.fields.filter((f) => DEMOGRAPHIC_KEY_RE.test(f.key || ""));
    const limbFields = section.fields.filter((f) => !DEMOGRAPHIC_KEY_RE.test(f.key || ""));
    const right = state.limbData?.right || {};
    const left = state.limbData?.left || {};
    return sharedFields.some((f) => isFilled(f, state)) || limbFields.some((f) => isFilled(f, right)) || limbFields.some((f) => isFilled(f, left));
  }
  return section.fields.some((f) => isFilled(f, state));
}

// Small labeled divider used to separate Right/Left content within History,
// Examination, and Management Pathway sections when the patient's Side is
// set to Bilateral, so each limb's independent documentation is visually
// distinct without needing a whole separate UI mode.
function LimbHeader({ limb }) {
  const label = limb === "right" ? "Right side" : "Left side";
  return (
    <div className="flex items-center gap-2 mb-2 mt-4 first:mt-0">
      <span className="rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide shrink-0" style={{ background: T.tealTint, color: T.tealDark }}>{label}</span>
      <div className="flex-1 h-px" style={{ background: T.border }} />
    </div>
  );
}

// Used for trigger finger's per-digit assessment: each affected digit can
// be at a different stage and need different management, so it's not
// meaningfully "one exam" the way a single joint is - this mirrors
// LimbHeader's role but for digit instead of side.
function DigitHeader({ digit }) {
  return (
    <div className="flex items-center gap-2 mb-2 mt-4 first:mt-0">
      <span className="rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide shrink-0" style={{ background: T.tealTint, color: T.tealDark }}>{digit}</span>
      <div className="flex-1 h-px" style={{ background: T.border }} />
    </div>
  );
}

// Shown wherever "injection" turns out to be part of today's plan -
// whether reached via the Management Pathway itself or picked as an
// alternative option. Asks timing first (so "agreed" always has a
// concrete timing attached) then agreement, mirroring the surgery prompt's
// never-assume-consent approach.
function InjectionPrompt({ label, detail, onChange }) {
  const d = detail || {};
  const set = (key, val) => onChange({ ...d, [key]: val });
  return (
    <>
      <SubLabel>{label ? `${label} \u2014 injection timing` : "Injection timing"}</SubLabel>
      <ButtonSelect options={["Today", "Scheduled for a later date"]} value={d.timing || null} onChange={(v) => set("timing", v)} columns={2} />
      {d.timing === "Scheduled for a later date" && (
        <TextField label="Specify date / timing" value={d.scheduledDate} onChange={(v) => set("scheduledDate", v)} placeholder="e.g. next Tuesday, or a specific date" />
      )}
      <SubLabel>{label ? `${label} \u2014 did the patient agree to the injection?` : "Did the patient agree to the injection?"}</SubLabel>
      <ButtonSelect options={["Agreed", "Not agreed"]} value={d.agreement || null} onChange={(v) => set("agreement", v)} columns={2} />
    </>
  );
}

// Shown once the clinician has recorded that the patient agreed to discuss
// surgery (the same gate as the surgery-agreement prompt). Lets them select
// which specific procedure(s) were discussed/elected from that condition's
// standard operative options - multiple selections are allowed, since more
// than one procedure is often discussed together (e.g. distal clavicle
// excision alongside a rotator cuff repair) - plus free text for anything
// not on the list.
function SurgicalDiscussionPrompt({ label, conditionId, selected, onSelectedChange, otherText, onOtherTextChange, complicationsDiscussed, onComplicationsDiscussedChange, patientState }) {
  const options = [...surgicalOptionsFor(conditionId), "Other"];
  const procedures = (selected || []).filter((p) => p !== "Other");
  if ((selected || []).includes("Other") && otherText && otherText.trim()) procedures.push(otherText.trim());
  const complicationsSentence = procedures.length ? buildComplicationsSentence(procedures, patientState) : null;

  return (
    <>
      <SubLabel>{label ? `${label} \u2014 procedure(s) discussed / elected` : "Procedure(s) discussed / elected"}</SubLabel>
      <CheckboxGroup options={options} selected={selected || []} onChange={onSelectedChange} />
      {(selected || []).includes("Other") && (
        <TextField label="Specify procedure" value={otherText} onChange={onOtherTextChange} placeholder="Procedure not listed above" />
      )}
      {complicationsSentence && (
        <>
          <div className="rounded-xl px-4 py-3 mt-3 mb-2" style={{ background: T.slateChip, border: `1px dashed ${T.borderStrong}` }}>
            <div className="text-[12px] font-semibold uppercase tracking-wide mb-1.5" style={{ color: T.inkSoft }}>Tailored complications (reference)</div>
            <div className="text-[13px]" style={{ color: T.inkSoft }}>{complicationsSentence}</div>
          </div>
          <SubLabel>{label ? `${label} \u2014 were these complications discussed with the patient?` : "Were these complications discussed with the patient?"}</SubLabel>
          <ButtonSelect options={["Yes", "No"]} value={complicationsDiscussed === true ? "Yes" : complicationsDiscussed === false ? "No" : null} onChange={(v) => onComplicationsDiscussedChange(v === "Yes")} columns={2} />
        </>
      )}
    </>
  );
}

/* ============================================================================
   CONDITION TEMPLATE SCREEN
============================================================================ */
function RelatedConditionsBar({ conditionId, sessionOrder, onOpen }) {
  const items = (RELATED_CONDITIONS[conditionId] || []).map((id) => findConditionById(id)).filter(Boolean);
  if (!items.length) return null;
  return (
    <div className="mb-3">
      <div className="text-[11px] font-semibold uppercase tracking-wide mb-1.5" style={{ color: T.inkSoft }}>Related conditions</div>
      <div className="flex flex-wrap gap-2">
        {items.map((c) => {
          const already = sessionOrder.includes(c.id);
          return (
            <button
              key={c.id}
              onClick={() => onOpen(c)}
              className="rounded-full px-3 py-1.5 text-[12.5px] font-medium flex items-center gap-1 active:scale-95 transition"
              style={{ background: already ? T.tealTint : T.slateChip, color: already ? T.tealDark : T.ink, border: `1px solid ${already ? T.teal : T.border}` }}
            >
              {already && <Check size={12} />}
              {c.name}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ConditionTemplate({ condition, state, onFieldChange, session, onOpenCondition, onResetCondition, onBack }) {
  const [openSection, setOpenSection] = useState(condition.sections[0]?.id || null);
  const [flagsOpen, setFlagsOpen] = useState(false);
  const [noteOpen, setNoteOpen] = useState(false);
  const [noteScope, setNoteScope] = useState("this"); // "this" | "session"
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);

  const setField = useCallback((key, val) => onFieldChange({ [key]: val }), [onFieldChange]);
  const toggleSection = (id) => setOpenSection((cur) => (cur === id ? null : id));
  const hasMultipleActive = session.order.length > 1;

  // When Side is set to Bilateral, History, Examination, Imaging, and
  // Diagnosis Classification are documented independently per limb (imaging
  // and the resulting diagnosis genuinely differ per side and feed into the
  // pathway below), and the Management Pathway is walked independently per
  // limb too. Per-limb values live in a nested state.limbData.{right,left}
  // bucket rather than the flat top-level state used everywhere else, so
  // unilateral documentation (the vast majority of encounters) is
  // completely unaffected by this feature.
  const isBilateral = state.side === "Bilateral";
  const rightLimbState = state.limbData?.right || {};
  const leftLimbState = state.limbData?.left || {};
  const setRightField = useCallback(
    (key, val) => onFieldChange({ limbData: { ...(state.limbData || {}), right: { ...(state.limbData?.right || {}), [key]: val } } }),
    [onFieldChange, state.limbData]
  );
  const setLeftField = useCallback(
    (key, val) => onFieldChange({ limbData: { ...(state.limbData || {}), left: { ...(state.limbData?.left || {}), [key]: val } } }),
    [onFieldChange, state.limbData]
  );

  // Trigger finger: each affected digit can be at a different stage and
  // need different management (one digit might settle with an injection
  // while another needs release), so exam findings and the Management
  // Pathway are assessed independently per digit rather than once for the
  // whole hand. Mirrors the bilateral limb pattern above, keyed by digit
  // name instead of side, in its own state.digitData bucket.
  const isPerDigitCondition = condition.id === "trigger-finger";
  const affectedDigitsList = isPerDigitCondition ? state.affectedDigits || [] : [];
  const setDigitField = useCallback(
    (digit, key, val) => onFieldChange({ digitData: { ...(state.digitData || {}), [digit]: { ...(state.digitData?.[digit] || {}), [key]: val } } }),
    [onFieldChange, state.digitData]
  );
  const setDigitPathwayAnswer = useCallback(
    (digit, q, a) =>
      onFieldChange({
        pathwayAnswersByDigit: { ...(state.pathwayAnswersByDigit || {}), [digit]: { ...(state.pathwayAnswersByDigit?.[digit] || {}), [q]: a } },
      }),
    [onFieldChange, state.pathwayAnswersByDigit]
  );
  const setDigitSurgeryAgreement = useCallback(
    (digit, val) => onFieldChange({ pathwaySurgeryAgreementByDigit: { ...(state.pathwaySurgeryAgreementByDigit || {}), [digit]: val } }),
    [onFieldChange, state.pathwaySurgeryAgreementByDigit]
  );
  const setDigitAltOptions = useCallback(
    (digit, key, val) => onFieldChange({ pathwayAltByDigit: { ...(state.pathwayAltByDigit || {}), [digit]: { ...(state.pathwayAltByDigit?.[digit] || {}), [key]: val } } }),
    [onFieldChange, state.pathwayAltByDigit]
  );
  const setDigitInjectionDetail = useCallback(
    (digit, detail) => onFieldChange({ injectionDetailByDigit: { ...(state.injectionDetailByDigit || {}), [digit]: detail } }),
    [onFieldChange, state.injectionDetailByDigit]
  );
  const setDigitSurgicalDiscussion = useCallback(
    (digit, key, val) => onFieldChange({ surgicalDiscussionByDigit: { ...(state.surgicalDiscussionByDigit || {}), [digit]: { ...(state.surgicalDiscussionByDigit?.[digit] || {}), [key]: val } } }),
    [onFieldChange, state.surgicalDiscussionByDigit]
  );

  // Typical Presentation is now a clickable checklist (one field, or a few
  // grouped ones for conditions with alternate presentation patterns), all
  // keyed with a "typicalPresentation" prefix. Whatever's checked there is
  // pooled here (case-insensitive, trimmed) so the same finding doesn't
  // have to be re-selected in Risk Factors or History \u2014 those checkboxes
  // simply don't show an option once it's already been captured here.
  // Typical Patient content is never split per limb, so this pool is always
  // read from the shared top-level state.
  const presentationPool = useMemo(() => {
    const typical = condition.sections.find((s) => s.id === "typical");
    const pool = new Set();
    if (!typical) return pool;
    typical.fields.forEach((f) => {
      if (f.type === "checkbox" && /^typicalPresentation/i.test(f.key || "")) {
        (state[f.key] || []).forEach((v) => pool.add(String(v).trim().toLowerCase()));
      }
    });
    return pool;
  }, [condition, state]);

  const dedupeFields = useCallback(
    (fields) => {
      if (!presentationPool.size) return fields;
      return fields
        .map((f) => {
          if (f.type === "conditional") return { ...f, fields: dedupeFields(f.fields) };
          if (f.type !== "checkbox" || /^typicalPresentation/i.test(f.key || "") || !f.options) return f;
          const filtered = f.options.filter((opt) => !presentationPool.has(String(opt).trim().toLowerCase()));
          if (filtered.length === f.options.length) return f;
          if (!filtered.length) return null;
          return { ...f, options: filtered };
        })
        .filter(Boolean);
    },
    [presentationPool]
  );

  const note = useMemo(
    () => (noteScope === "session" && hasMultipleActive ? buildCombinedNote(session) : buildNote(condition, state)),
    [condition, state, noteScope, hasMultipleActive, session]
  );

  const copyNote = async () => {
    const ok = await copyTextRobust(note);
    if (ok) {
      setCopied(true);
      setCopyError(false);
      setTimeout(() => setCopied(false), 1800);
    } else {
      setCopied(false);
      setCopyError(true);
      setTimeout(() => setCopyError(false), 4000);
    }
  };

  const doReset = () => {
    onResetCondition();
    setConfirmReset(false);
    setNoteOpen(false);
    setOpenSection(condition.sections[0]?.id || null);
  };

  const redFlagsChecked = state.redFlagsChecked || [];
  const toggleRedFlag = (i) => {
    const next = redFlagsChecked.includes(i) ? redFlagsChecked.filter((x) => x !== i) : [...redFlagsChecked, i];
    setField("redFlagsChecked", next);
    // Checking a flag as present directly contradicts an existing "none
    // present" confirmation, so it's cleared automatically rather than
    // leaving a stale, contradictory state for the clinician to notice.
    if (!redFlagsChecked.includes(i) && state.redFlagsReviewed) setField("redFlagsReviewed", false);
  };
  const urgentFlagsChecked = state.urgentFlagsChecked || [];
  const toggleUrgentFlag = (i) => {
    const next = urgentFlagsChecked.includes(i) ? urgentFlagsChecked.filter((x) => x !== i) : [...urgentFlagsChecked, i];
    setField("urgentFlagsChecked", next);
    if (!urgentFlagsChecked.includes(i) && state.redFlagsReviewed) setField("redFlagsReviewed", false);
  };
  const noFlagsChecked = redFlagsChecked.length === 0 && urgentFlagsChecked.length === 0;
  const toggleRedFlagsReviewed = () => setField("redFlagsReviewed", !state.redFlagsReviewed);
  const totalFlagsChecked = redFlagsChecked.length + urgentFlagsChecked.length;
  // Live progress so the clinician can see how much of the template is
  // documented without scrolling the whole section list.
  const sectionsDone = condition.sections.filter((s) => sectionHasContent(s, state, condition.id)).length;

  return (
    <div className="min-h-screen pb-32" style={{ background: T.bg }}>
      <div className="sticky top-0 z-30 flex items-center gap-2 px-3 py-3" style={{ background: T.surface, borderBottom: `1px solid ${T.border}`, boxShadow: "0 1px 3px rgba(16,30,43,0.04)" }}>
        <button onClick={onBack} className="p-2 -ml-1 active:opacity-60"><ArrowLeft size={22} color={T.ink} /></button>
        <div className="flex-1 min-w-0">
          <div className="font-bold text-[16px] truncate" style={{ color: T.ink }}>{condition.name}</div>
          <div className="text-[12px] capitalize" style={{ color: T.inkSoft }}>{condition.region} \u00b7 {sectionsDone}/{condition.sections.length} sections documented</div>
        </div>
        <button onClick={() => setFlagsOpen(true)} className="flex items-center gap-1 rounded-full px-3 py-2 active:scale-95" style={{ background: T.amberTint, border: `1px solid ${T.amber}` }}>
          <AlertTriangle size={16} color={T.amber} />
          <span className="text-[13px] font-semibold" style={{ color: T.amber }}>{totalFlagsChecked > 0 ? totalFlagsChecked : ""} Red flags</span>
        </button>
      </div>

      <div className="px-3 pt-3 max-w-2xl mx-auto">
        <RelatedConditionsBar conditionId={condition.id} sessionOrder={session.order} onOpen={onOpenCondition} />

        {condition.sections.map((section, sectionIdx) => {
          const nextSection = condition.sections[sectionIdx + 1];
          return (
          <CollapsibleSection
            key={section.id}
            index={section.index}
            title={section.title}
            subtitle={section.subtitle}
            isOpen={openSection === section.id}
            onToggle={() => toggleSection(section.id)}
            hasContent={sectionHasContent(section, state, condition.id)}
            nextTitle={nextSection ? nextSection.title : null}
            onNext={nextSection ? () => setOpenSection(nextSection.id) : null}
          >
            {isPerDigitCondition && section.id === "pathway" ? (
              <>
                <div className="text-[12.5px] mb-3 italic" style={{ color: T.inkSoft }}>
                  Pathway suggests next steps for each affected digit independently, based on your answers \u2014 clinical judgement remains central.
                </div>
                {affectedDigitsList.length === 0 ? (
                  <div className="text-[13px] rounded-xl px-4 py-3" style={{ color: T.inkSoft, background: T.slateChip, border: `1px solid ${T.border}` }}>
                    Select affected digit(s) in Focused History to begin digit-specific management.
                  </div>
                ) : (
                  affectedDigitsList.map((digit) => {
                    const digitAnswers = state.pathwayAnswersByDigit?.[digit] || {};
                    const digitAlt = state.pathwayAltByDigit?.[digit] || {};
                    return (
                      <div key={digit}>
                        <DigitHeader digit={digit} />
                        <PathwayFlow
                          schema={condition.pathway}
                          answers={digitAnswers}
                          onAnswer={(q, a) => setDigitPathwayAnswer(digit, q, a)}
                          priorTreatmentGiven={(state.prevTreatment || []).length > 0}
                        />
                        {pathwayTrailInvolvesSurgery(condition.pathway, digitAnswers) && (
                          <>
                            <SubLabel>{digit} — did the patient agree to proceed with surgery?</SubLabel>
                            <ButtonSelect options={["Agreed", "Not agreed"]} value={state.pathwaySurgeryAgreementByDigit?.[digit] || null} onChange={(v) => setDigitSurgeryAgreement(digit, v)} columns={2} />
                          </>
                        )}
                        {state.pathwaySurgeryAgreementByDigit?.[digit] === "Agreed" && (
                          <SurgicalDiscussionPrompt
                            label={digit}
                            conditionId={condition.id}
                            selected={state.surgicalDiscussionByDigit?.[digit]?.selected}
                            onSelectedChange={(v) => setDigitSurgicalDiscussion(digit, "selected", v)}
                            otherText={state.surgicalDiscussionByDigit?.[digit]?.otherText}
                            onOtherTextChange={(v) => setDigitSurgicalDiscussion(digit, "otherText", v)}
                            complicationsDiscussed={state.surgicalDiscussionByDigit?.[digit]?.complicationsDiscussed}
                            onComplicationsDiscussedChange={(v) => setDigitSurgicalDiscussion(digit, "complicationsDiscussed", v)}
                            patientState={state}
                          />
                        )}
                        <div className="text-[12.5px] mt-3 mb-2" style={{ color: T.inkSoft }}>Or choose a different plan for this digit</div>
                        <CheckboxGroup options={PATHWAY_ALT_OPTIONS} selected={digitAlt.options || []} onChange={(v) => setDigitAltOptions(digit, "options", v)} />
                        {(digitAlt.options || []).includes("Other") && (
                          <TextField label="Specify alternative option" value={digitAlt.optionsOther} onChange={(v) => setDigitAltOptions(digit, "optionsOther", v)} />
                        )}
                        <TextField label="Or write the plan manually" value={digitAlt.manualPlan} onChange={(v) => setDigitAltOptions(digit, "manualPlan", v)} placeholder="Optional — free text plan" />
                        {planInvolvesInjection(condition.pathway, digitAnswers, digitAlt.options) && (
                          <InjectionPrompt label={digit} detail={state.injectionDetailByDigit?.[digit]} onChange={(d) => setDigitInjectionDetail(digit, d)} />
                        )}
                      </div>
                    );
                  })
                )}
              </>
            ) : isPerDigitCondition && section.id === "exam" ? (
              (() => {
                const digitSpecificKeys = new Set(["palpation", "activeFlexion", "activeExtension", "passiveMotion", "compositeFist", "tendonGliding", "triggerSeverity"]);
                const sharedFields = section.fields.filter((f) => !digitSpecificKeys.has(f.key));
                const perDigitFields = section.fields.filter((f) => digitSpecificKeys.has(f.key));
                return (
                  <>
                    {sharedFields.map((f, i) => <Field key={`s-${i}`} field={f} state={state} setField={setField} region={condition.region} />)}
                    {affectedDigitsList.length === 0 ? (
                      <div className="text-[13px] rounded-xl px-4 py-3 mt-3" style={{ color: T.inkSoft, background: T.slateChip, border: `1px solid ${T.border}` }}>
                        Select affected digit(s) in Focused History to assess each digit independently.
                      </div>
                    ) : (
                      affectedDigitsList.map((digit) => (
                        <div key={digit}>
                          <DigitHeader digit={digit} />
                          {perDigitFields.map((f, i) => (
                            <Field key={`${digit}-${i}`} field={f} state={state.digitData?.[digit] || {}} setField={(k, v) => setDigitField(digit, k, v)} region={condition.region} />
                          ))}
                        </div>
                      ))
                    )}
                  </>
                );
              })()
            ) : section.id === "pathway" ? (
              <>
                <div className="text-[12.5px] mb-3 italic" style={{ color: T.inkSoft }}>
                  {isBilateral
                    ? "Pathway suggests next steps for each side independently, based on your answers \u2014 clinical judgement remains central."
                    : "Pathway suggests next steps based on your answers \u2014 clinical judgement remains central."}
                </div>
                {isBilateral ? (
                  <>
                    <LimbHeader limb="right" />
                    <PathwayFlow schema={condition.pathway} answers={state.pathwayAnswersRight || {}} onAnswer={(q, a) => setField("pathwayAnswersRight", { ...(state.pathwayAnswersRight || {}), [q]: a })} priorTreatmentGiven={((state.limbData?.right?.prevTreatment) || []).length > 0} />
                    {pathwayTrailInvolvesSurgery(condition.pathway, state.pathwayAnswersRight || {}) && (
                      <>
                        <SubLabel>Right side — did the patient agree to proceed with surgery?</SubLabel>
                        <ButtonSelect options={["Agreed", "Not agreed"]} value={state.pathwaySurgeryAgreementRight || null} onChange={(v) => setField("pathwaySurgeryAgreementRight", v)} columns={2} />
                      </>
                    )}
                    {state.pathwaySurgeryAgreementRight === "Agreed" && (
                      <SurgicalDiscussionPrompt
                        label="Right side"
                        conditionId={condition.id}
                        selected={state.surgicalDiscussionRight?.selected}
                        onSelectedChange={(v) => setField("surgicalDiscussionRight", { ...(state.surgicalDiscussionRight || {}), selected: v })}
                        otherText={state.surgicalDiscussionRight?.otherText}
                        onOtherTextChange={(v) => setField("surgicalDiscussionRight", { ...(state.surgicalDiscussionRight || {}), otherText: v })}
                        complicationsDiscussed={state.surgicalDiscussionRight?.complicationsDiscussed}
                        onComplicationsDiscussedChange={(v) => setField("surgicalDiscussionRight", { ...(state.surgicalDiscussionRight || {}), complicationsDiscussed: v })}
                        patientState={state}
                      />
                    )}
                    {planInvolvesInjection(condition.pathway, state.pathwayAnswersRight || {}, state.pathwayAltOptions) && (
                      <InjectionPrompt label="Right side" detail={state.injectionDetailRight} onChange={(d) => setField("injectionDetailRight", d)} />
                    )}
                    <LimbHeader limb="left" />
                    <PathwayFlow schema={condition.pathway} answers={state.pathwayAnswersLeft || {}} onAnswer={(q, a) => setField("pathwayAnswersLeft", { ...(state.pathwayAnswersLeft || {}), [q]: a })} priorTreatmentGiven={((state.limbData?.left?.prevTreatment) || []).length > 0} />
                    {pathwayTrailInvolvesSurgery(condition.pathway, state.pathwayAnswersLeft || {}) && (
                      <>
                        <SubLabel>Left side — did the patient agree to proceed with surgery?</SubLabel>
                        <ButtonSelect options={["Agreed", "Not agreed"]} value={state.pathwaySurgeryAgreementLeft || null} onChange={(v) => setField("pathwaySurgeryAgreementLeft", v)} columns={2} />
                      </>
                    )}
                    {state.pathwaySurgeryAgreementLeft === "Agreed" && (
                      <SurgicalDiscussionPrompt
                        label="Left side"
                        conditionId={condition.id}
                        selected={state.surgicalDiscussionLeft?.selected}
                        onSelectedChange={(v) => setField("surgicalDiscussionLeft", { ...(state.surgicalDiscussionLeft || {}), selected: v })}
                        otherText={state.surgicalDiscussionLeft?.otherText}
                        onOtherTextChange={(v) => setField("surgicalDiscussionLeft", { ...(state.surgicalDiscussionLeft || {}), otherText: v })}
                        complicationsDiscussed={state.surgicalDiscussionLeft?.complicationsDiscussed}
                        onComplicationsDiscussedChange={(v) => setField("surgicalDiscussionLeft", { ...(state.surgicalDiscussionLeft || {}), complicationsDiscussed: v })}
                        patientState={state}
                      />
                    )}
                    {planInvolvesInjection(condition.pathway, state.pathwayAnswersLeft || {}, state.pathwayAltOptions) && (
                      <InjectionPrompt label="Left side" detail={state.injectionDetailLeft} onChange={(d) => setField("injectionDetailLeft", d)} />
                    )}
                  </>
                ) : (
                  <>
                    <PathwayFlow schema={condition.pathway} answers={state.pathwayAnswers || {}} onAnswer={(q, a) => setField("pathwayAnswers", { ...(state.pathwayAnswers || {}), [q]: a })} priorTreatmentGiven={(state.prevTreatment || []).length > 0} />
                    {pathwayTrailInvolvesSurgery(condition.pathway, state.pathwayAnswers || {}) && (
                      <>
                        <SubLabel>Did the patient agree to proceed with surgery?</SubLabel>
                        <ButtonSelect options={["Agreed", "Not agreed"]} value={state.pathwaySurgeryAgreement || null} onChange={(v) => setField("pathwaySurgeryAgreement", v)} columns={2} />
                      </>
                    )}
                    {state.pathwaySurgeryAgreement === "Agreed" && (
                      <SurgicalDiscussionPrompt
                        conditionId={condition.id}
                        selected={state.surgicalDiscussion?.selected}
                        onSelectedChange={(v) => setField("surgicalDiscussion", { ...(state.surgicalDiscussion || {}), selected: v })}
                        otherText={state.surgicalDiscussion?.otherText}
                        onOtherTextChange={(v) => setField("surgicalDiscussion", { ...(state.surgicalDiscussion || {}), otherText: v })}
                        complicationsDiscussed={state.surgicalDiscussion?.complicationsDiscussed}
                        onComplicationsDiscussedChange={(v) => setField("surgicalDiscussion", { ...(state.surgicalDiscussion || {}), complicationsDiscussed: v })}
                        patientState={state}
                      />
                    )}
                    {planInvolvesInjection(condition.pathway, state.pathwayAnswers || {}, state.pathwayAltOptions) && (
                      <InjectionPrompt detail={state.injectionDetail} onChange={(d) => setField("injectionDetail", d)} />
                    )}
                  </>
                )}

                <SubLabel>Or choose alternative treatment options</SubLabel>
                <CheckboxGroup options={PATHWAY_ALT_OPTIONS} selected={state.pathwayAltOptions || []} onChange={(v) => setField("pathwayAltOptions", v)} />
                {(state.pathwayAltOptions || []).includes("Other") && (
                  <TextField label="Specify alternative option" value={state.pathwayAltOptionsOther} onChange={(v) => setField("pathwayAltOptionsOther", v)} />
                )}
                <TextField label="Or write the plan manually" value={state.pathwayManualPlan} onChange={(v) => setField("pathwayManualPlan", v)} placeholder="Optional — free text plan" />
              </>
            ) : section.id === "redflags" ? (
              <>
                {condition.urgentFlags && condition.urgentFlags.length > 0 && (
                  <>
                    <div className="text-[12px] font-bold uppercase tracking-wide mb-2" style={{ color: T.red }}>Urgent — reassess immediately</div>
                    <RedFlagChecklist items={condition.urgentFlags} checked={urgentFlagsChecked} onToggle={toggleUrgentFlag} />
                    <div className="text-[12px] font-bold uppercase tracking-wide mb-2 mt-4" style={{ color: T.amber }}>When to stop and reconsider</div>
                  </>
                )}
                <RedFlagChecklist items={condition.redFlags} checked={redFlagsChecked} onToggle={toggleRedFlag} />
                {noFlagsChecked && (
                  <button
                    onClick={toggleRedFlagsReviewed}
                    className="w-full flex items-center gap-2.5 rounded-xl px-4 py-3.5 mt-4 text-left active:scale-95 transition"
                    style={{ background: state.redFlagsReviewed ? T.greenTint : T.slateChip, border: `1px solid ${state.redFlagsReviewed ? T.green : T.border}` }}
                  >
                    {state.redFlagsReviewed ? <CheckCircle2 size={20} color={T.green} /> : <Circle size={20} color={T.borderStrong} />}
                    <span className="text-[14px] font-semibold" style={{ color: state.redFlagsReviewed ? T.green : T.ink }}>Red flags reviewed — none present</span>
                  </button>
                )}
              </>
            ) : isBilateral && (section.id === "history" || section.id === "exam" || section.id === "imaging" || section.id === "diagnosis") ? (
              (() => {
                // Patient-level facts (age, gender, dominance, occupation,
                // work demand, and the Side selector itself) are asked once
                // regardless of laterality \u2014 only genuinely limb-specific
                // content (symptoms, exam findings, imaging, diagnosis) is
                // split into independent Right/Left panels.
                const sharedFields = section.fields.filter((f) => DEMOGRAPHIC_KEY_RE.test(f.key || ""));
                const limbFields = dedupeFields(section.fields.filter((f) => !DEMOGRAPHIC_KEY_RE.test(f.key || "")));
                return (
                  <>
                    {sharedFields.map((f, i) => <Field key={`s-${i}`} field={f} state={state} setField={setField} region={condition.region} />)}
                    <LimbHeader limb="right" />
                    {limbFields.map((f, i) => <Field key={`r-${i}`} field={f} state={rightLimbState} setField={setRightField} region={condition.region} />)}
                    <LimbHeader limb="left" />
                    {limbFields.map((f, i) => <Field key={`l-${i}`} field={f} state={leftLimbState} setField={setLeftField} region={condition.region} />)}
                  </>
                );
              })()
            ) : (
              dedupeFields(section.fields).map((f, i) => <Field key={i} field={f} state={state} setField={setField} region={condition.region} />)
            )}
          </CollapsibleSection>
          );
        })}
      </div>

      <div className="fixed bottom-0 left-0 right-0 z-30 flex gap-2 px-3 py-3" style={{ background: T.surface, borderTop: `1px solid ${T.border}` }}>
        <button onClick={() => setConfirmReset(true)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.redTint, color: T.red, border: `1px solid ${T.red}`, minHeight: 48 }}>
          <RotateCcw size={17} /> New patient
        </button>
        <button onClick={() => { setNoteScope("this"); setNoteOpen(true); }} className="flex-1 rounded-xl px-4 py-3 font-semibold text-[15px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
          Preview clinic note
        </button>
      </div>

      {noteOpen && (
        <div className="fixed inset-0 z-40 flex items-end sm:items-center justify-center" style={{ background: "rgba(16,30,43,0.5)" }} onClick={() => setNoteOpen(false)}>
          <div className="w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl" style={{ background: T.surface, display: "flex", flexDirection: "column", maxHeight: "88vh", boxShadow: "0 -4px 24px rgba(16,30,43,0.12)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center gap-1 -ml-1 p-1 active:opacity-60" aria-label="Back to editing">
                <ArrowLeft size={20} color={T.ink} />
              </button>
              <span className="font-bold text-[15px] flex-1" style={{ color: T.ink }}>Clinic note</span>
            </div>
            {hasMultipleActive && (
              <div className="flex gap-2 px-4 pt-3">
                <button onClick={() => setNoteScope("this")} className="flex-1 rounded-lg py-2 text-[13px] font-semibold" style={{ background: noteScope === "this" ? T.teal : T.slateChip, color: noteScope === "this" ? "#fff" : T.ink }}>
                  This condition
                </button>
                <button onClick={() => setNoteScope("session")} className="flex-1 rounded-lg py-2 text-[13px] font-semibold" style={{ background: noteScope === "session" ? T.teal : T.slateChip, color: noteScope === "session" ? "#fff" : T.ink }}>
                  Full session ({session.order.length})
                </button>
              </div>
            )}
            <div className="px-4 py-3" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
              <pre className="whitespace-pre-wrap text-[13px] leading-relaxed" style={{ color: T.ink, fontFamily: "ui-monospace, monospace", overflow: "visible", margin: 0 }}>{note}</pre>
            </div>
            <div className="px-4 py-3 flex flex-col gap-2" style={{ borderTop: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
                <ArrowLeft size={17} /> Back to editing
              </button>
              <button onClick={copyNote} className="flex items-center justify-center gap-2 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
                {copied ? <Check size={17} /> : <Copy size={17} />}
                {copied ? "Copied" : "Copy to clipboard"}
              </button>
              {copyError && (
                <div className="text-[12.5px] text-center" style={{ color: T.red }}>
                  Couldn't copy automatically \u2014 tap and hold the note above to select and copy it manually.
                </div>
              )}
              <button onClick={() => setConfirmReset(true)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.redTint, color: T.red, border: `1px solid ${T.red}`, minHeight: 48 }}>
                <RotateCcw size={17} /> New patient
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmReset && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-6" style={{ background: "rgba(16,30,43,0.5)" }}>
          <div className="w-full max-w-sm rounded-2xl p-5" style={{ background: T.surface, boxShadow: "0 8px 32px rgba(16,30,43,0.18)" }}>
            <div className="font-bold text-[15px] mb-1.5" style={{ color: T.ink }}>Start a new patient?</div>
            <div className="text-[13.5px] mb-4" style={{ color: T.inkSoft }}>This clears every entry for {condition.name} \u2014 history, examination, pathway progress, and red flags \u2014 so it's ready for the next patient. The template itself stays selected. Other conditions in this session are unaffected. This cannot be undone.</div>
            <div className="flex gap-2">
              <button onClick={() => setConfirmReset(false)} className="flex-1 rounded-xl px-4 py-2.5 font-semibold text-[14px]" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}` }}>Cancel</button>
              <button onClick={doReset} className="flex-1 rounded-xl px-4 py-2.5 font-semibold text-[14px]" style={{ background: T.red, color: "#fff" }}>Start new patient</button>
            </div>
          </div>
        </div>
      )}

      <RedFlagPanel
        redFlags={condition.redFlags}
        checked={redFlagsChecked}
        onToggle={toggleRedFlag}
        urgentFlags={condition.urgentFlags}
        urgentChecked={urgentFlagsChecked}
        onToggleUrgent={toggleUrgentFlag}
        open={flagsOpen}
        onClose={() => setFlagsOpen(false)}
        reviewed={state.redFlagsReviewed}
        onToggleReviewed={toggleRedFlagsReviewed}
      />
    </div>
  );
}

/* ============================================================================
   NAVIGATION: Region picker → Condition list → Template
============================================================================ */
// The very first screen a clinician sees: whether this is a new patient
// encounter (routes to the existing region-picker template flow, unchanged)
// or a follow-up on an existing diagnosis (routes to the lighter-weight
// follow-up workflow below). Choosing either doesn't touch any session data
// already entered - it's purely a navigation fork, so switching between
// them later (via Home) never loses work.
// beforeinstallprompt only exists on Chromium-based browsers (Chrome, Edge,
// Android). iOS Safari never fires it - there is no programmatic install
// API there at all, so it needs manual "Add to Home Screen" instructions
// instead of a button that would silently do nothing.
function useInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    setIsStandalone(
      (typeof window !== "undefined" && window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) ||
        (typeof window !== "undefined" && window.navigator && window.navigator.standalone === true)
    );

    const onBeforeInstall = (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    const onInstalled = () => {
      setDeferredPrompt(null);
      setIsStandalone(true);
    };
    window.addEventListener("beforeinstallprompt", onBeforeInstall);
    window.addEventListener("appinstalled", onInstalled);
    return () => {
      window.removeEventListener("beforeinstallprompt", onBeforeInstall);
      window.removeEventListener("appinstalled", onInstalled);
    };
  }, []);

  // iPadOS 13+ reports itself as desktop Safari ("Macintosh") in the user
  // agent, not "iPad" - the standard workaround is checking for touch
  // support on what claims to be a Mac, since real Macs aren't touchscreens.
  const isIOS =
    typeof navigator !== "undefined" &&
    (/iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1));

  const promptInstall = useCallback(async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    await deferredPrompt.userChoice;
    setDeferredPrompt(null);
  }, [deferredPrompt]);

  return { canInstall: !!deferredPrompt, isIOS, isStandalone, promptInstall };
}

function InstallPrompt() {
  const { canInstall, isIOS, isStandalone, promptInstall } = useInstallPrompt();
  const [dismissed, setDismissed] = useState(false);

  if (isStandalone || dismissed) return null;
  if (!canInstall && !isIOS) return null;

  return (
    <div className="rounded-2xl p-4 mb-5 flex items-start gap-3" style={{ background: T.tealTint, border: `1px solid ${T.teal}` }}>
      <div className="flex-1 min-w-0">
        <div className="font-bold text-[14px]" style={{ color: T.tealDark }}>Install UpperTrack</div>
        {canInstall ? (
          <>
            <div className="text-[13px] mt-0.5" style={{ color: T.inkSoft }}>Add it to your home screen for one-tap access during clinic, and offline use.</div>
            <button onClick={promptInstall} className="mt-2.5 rounded-lg px-3.5 py-2 font-semibold text-[13px] active:scale-95 transition" style={{ background: T.tealDark, color: "#fff" }}>
              Install app
            </button>
          </>
        ) : (
          <div className="text-[13px] mt-0.5" style={{ color: T.inkSoft }}>Tap the Share button below, then "Add to Home Screen", for one-tap access and offline use.</div>
        )}
      </div>
      <button onClick={() => setDismissed(true)} className="p-1 -mt-1 -mr-1 active:opacity-60" aria-label="Dismiss">
        <X size={18} color={T.tealDark} />
      </button>
    </div>
  );
}

