// One diagnosis's follow-up documentation block: reason for review,
// treatment given since last visit, outcome, a re-walk of that condition's
// own Management Pathway for the new plan, and a review-interval picker
// reusing that condition's own Standard Follow-up intervals. Kept as its
// own component (rather than inlined in FollowupVisitScreen) since each
// block manages its own open/closed state independently.
function FollowupConditionBlock({ index, condition, fuState, fullState, onChange, defaultOpen }) {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const set = (key, val) => onChange({ ...fuState, [key]: val });

  const followupSection = condition.sections.find((s) => s.id === "followup");
  const tableField = followupSection && (followupSection.fields || []).find((f) => f.type === "table");
  const intervalOptions = tableField ? [...tableField.rows.map((r) => r.left), "Final", "Other"] : ["Final", "Other"];

  const hasContent =
    (fuState.reason || []).length > 0 ||
    (fuState.treatmentOffered || []).length > 0 ||
    !!fuState.outcome ||
    Object.keys(fuState.pathwayAnswers || {}).length > 0 ||
    (fuState.planOptions || []).length > 0 ||
    !!(fuState.planManualText && fuState.planManualText.trim()) ||
    !!fuState.followUpInterval ||
    (fuState.nextReviewReason || []).length > 0;

  return (
    <CollapsibleSection index={index} title={condition.name} subtitle="Reason, treatment given, outcome, new plan" isOpen={isOpen} onToggle={() => setIsOpen((v) => !v)} hasContent={hasContent}>
      <SubLabel>Reason for review</SubLabel>
      <CheckboxGroup options={FOLLOWUP_REASON_OPTIONS} selected={fuState.reason || []} onChange={(v) => set("reason", v)} />
      {(fuState.reason || []).includes("Other") && (
        <TextField label="Specify reason" value={fuState.reasonOther} onChange={(v) => set("reasonOther", v)} />
      )}

      <SubLabel>Treatment given since last visit</SubLabel>
      <CheckboxGroup options={FOLLOWUP_TREATMENT_OPTIONS} selected={fuState.treatmentOffered || []} onChange={(v) => set("treatmentOffered", v)} />
      {(fuState.treatmentOffered || []).includes("Other") && (
        <TextField label="Specify treatment" value={fuState.treatmentOfferedOther} onChange={(v) => set("treatmentOfferedOther", v)} />
      )}

      <SubLabel>Outcome of treatment</SubLabel>
      <ButtonSelect options={FOLLOWUP_OUTCOME_OPTIONS} value={fuState.outcome || null} onChange={(v) => set("outcome", v)} columns={4} />
      <TextField label="Notes on current symptoms / findings" value={fuState.outcomeNotes} onChange={(v) => set("outcomeNotes", v)} placeholder="Optional" />

      <SubLabel>New plan of treatment</SubLabel>
      {condition.pathway ? (
        <>
          <div className="text-[12.5px] mb-3 italic" style={{ color: T.inkSoft }}>Pathway suggests next steps based on today's answers — clinical judgement remains central.</div>
          <PathwayFlow schema={condition.pathway} answers={fuState.pathwayAnswers || {}} onAnswer={(q, a) => set("pathwayAnswers", { ...(fuState.pathwayAnswers || {}), [q]: a })} priorTreatmentGiven={(fuState.treatmentOffered || []).length > 0} />
          {pathwayTrailInvolvesSurgery(condition.pathway, fuState.pathwayAnswers || {}) && (
            <>
              <SubLabel>Did the patient agree to proceed with surgery?</SubLabel>
              <ButtonSelect options={["Agreed", "Not agreed"]} value={fuState.pathwaySurgeryAgreement || null} onChange={(v) => set("pathwaySurgeryAgreement", v)} columns={2} />
            </>
          )}
          {fuState.pathwaySurgeryAgreement === "Agreed" && (
            <SurgicalDiscussionPrompt
              conditionId={condition.id}
              selected={fuState.surgicalDiscussion?.selected}
              onSelectedChange={(v) => set("surgicalDiscussion", { ...(fuState.surgicalDiscussion || {}), selected: v })}
              otherText={fuState.surgicalDiscussion?.otherText}
              onOtherTextChange={(v) => set("surgicalDiscussion", { ...(fuState.surgicalDiscussion || {}), otherText: v })}
              complicationsDiscussed={fuState.surgicalDiscussion?.complicationsDiscussed}
              onComplicationsDiscussedChange={(v) => set("surgicalDiscussion", { ...(fuState.surgicalDiscussion || {}), complicationsDiscussed: v })}
              patientState={fullState}
            />
          )}
        </>
      ) : (
        <div className="text-[13px]" style={{ color: T.inkSoft }}>No structured pathway available for this condition.</div>
      )}

      <div className="text-[12.5px] mt-4 mb-2" style={{ color: T.inkSoft }}>Or choose a different plan:</div>
      <CheckboxGroup options={FOLLOWUP_PLAN_OPTIONS} selected={fuState.planOptions || []} onChange={(v) => set("planOptions", v)} />
      {(fuState.planOptions || []).includes("Other") && (
        <TextField label="Specify plan" value={fuState.planOptionsOther} onChange={(v) => set("planOptionsOther", v)} />
      )}
      <TextField label="Or write the plan manually" value={fuState.planManualText} onChange={(v) => set("planManualText", v)} placeholder="Optional — free text plan" />
      {planInvolvesInjection(condition.pathway, fuState.pathwayAnswers || {}, fuState.planOptions) && (
        <InjectionPrompt detail={fuState.injectionDetail} onChange={(d) => set("injectionDetail", d)} />
      )}

      <SubLabel>Next review</SubLabel>
      <ButtonSelect options={intervalOptions} value={fuState.followUpInterval || null} onChange={(v) => set("followUpInterval", v)} columns={2} />
      {fuState.followUpInterval === "Other" && (
        <TextField label="Specify follow-up timing" value={fuState.followUpIntervalOther} onChange={(v) => set("followUpIntervalOther", v)} />
      )}
      {fuState.followUpInterval && fuState.followUpInterval !== "Final" && (
        <>
          <div className="mb-1 mt-3 text-[12px] font-semibold uppercase tracking-wide" style={{ color: T.inkSoft }}>Reason for follow-up</div>
          <CheckboxGroup options={FOLLOWUP_NEXT_REVIEW_REASON_OPTIONS} selected={fuState.nextReviewReason || []} onChange={(v) => set("nextReviewReason", v)} />
          {(fuState.nextReviewReason || []).includes("Other") && (
            <TextField label="Specify reason for follow-up" value={fuState.nextReviewReasonOther} onChange={(v) => set("nextReviewReasonOther", v)} />
          )}
        </>
      )}
    </CollapsibleSection>
  );
}

// Root screen for the Follow-up Visit flow: one FollowupConditionBlock per
// diagnosis selected in FollowupConditionPicker, plus a note preview/copy
// panel at the bottom matching the same UX as the initial-encounter note.
function FollowupVisitScreen({ conditionIds, session, onFieldChange, onBack, onGoHome }) {
  const [noteOpen, setNoteOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState(false);

  const conditions = conditionIds.map((id) => findConditionById(id)).filter(Boolean);
  const note = useMemo(() => buildCombinedFollowupNote(session, conditionIds), [session, conditionIds]);

  const copyNote = async () => {
    const ok = await copyTextRobust(note);
    if (ok) {
      setCopied(true);
      setCopyError(false);
      setTimeout(() => setCopied(false), 1800);
    } else {
      setCopied(false);
      setCopyError(true);
      setTimeout(() => setCopyError(false), 4000);
    }
  };

  return (
    <div className="min-h-screen pb-28" style={{ background: T.bg }}>
      <div className="px-4 pt-5 pb-2 max-w-2xl mx-auto">
        <button onClick={onBack} className="flex items-center gap-1.5 text-[13.5px] font-semibold mb-3 active:opacity-60" style={{ color: T.teal }}>
          <ArrowLeft size={16} /> Change diagnoses
        </button>
        <div className="text-[12px] font-semibold uppercase tracking-widest mb-1" style={{ color: T.teal }}>Follow-up Visit</div>
        <h1 className="text-[20px] font-bold mb-4" style={{ color: T.ink }}>{conditions.length} diagnos{conditions.length === 1 ? "is" : "es"} being reviewed</h1>
      </div>
      <div className="px-4 max-w-2xl mx-auto">
        {conditions.map((condition, i) => {
          const state = session.statesByConditionId[condition.id] || {};
          const fuState = state.followup || {};
          return (
            <FollowupConditionBlock
              key={condition.id}
              index={i + 1}
              condition={condition}
              fuState={fuState}
              fullState={state}
              onChange={(next) => onFieldChange(condition.id, { followup: next })}
              defaultOpen={i === 0}
            />
          );
        })}
      </div>

      <div className="fixed bottom-0 left-0 right-0 z-30 px-3 py-3" style={{ background: T.surface, borderTop: `1px solid ${T.border}` }}>
        <div className="max-w-2xl mx-auto flex gap-2">
          <button onClick={onGoHome} className="rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
            Home
          </button>
          <button onClick={() => setNoteOpen(true)} className="flex-1 rounded-xl px-4 py-3 font-semibold text-[15px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
            Preview follow-up note
          </button>
        </div>
      </div>

      {noteOpen && (
        <div className="fixed inset-0 z-40 flex items-end sm:items-center justify-center" style={{ background: "rgba(16,30,43,0.5)" }} onClick={() => setNoteOpen(false)}>
          <div className="w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl" style={{ background: T.surface, display: "flex", flexDirection: "column", maxHeight: "88vh", boxShadow: "0 -4px 24px rgba(16,30,43,0.12)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center gap-1 -ml-1 p-1 active:opacity-60" aria-label="Back to editing">
                <ArrowLeft size={20} color={T.ink} />
              </button>
              <span className="font-bold text-[15px] flex-1" style={{ color: T.ink }}>Follow-up note</span>
            </div>
            <div className="px-4 py-3" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
              <pre className="whitespace-pre-wrap text-[13px] leading-relaxed" style={{ color: T.ink, fontFamily: "ui-monospace, monospace", overflow: "visible", margin: 0 }}>{note}</pre>
            </div>
            <div className="px-4 py-3 flex flex-col gap-2" style={{ borderTop: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
                <ArrowLeft size={17} /> Back to editing
              </button>
              <button onClick={copyNote} className="flex items-center justify-center gap-2 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
                {copied ? <Check size={17} /> : <Copy size={17} />}
                {copied ? "Copied" : "Copy to clipboard"}
              </button>
              {copyError && (
                <div className="text-[12.5px] text-center" style={{ color: T.red }}>
                  Couldn't copy automatically \u2014 tap and hold the note above to select and copy it manually.
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// One procedure's post-operative documentation block. Ordered to follow how
// a surgeon actually thinks through a post-op review: what was done and
// when, why we're seeing them today, how they're doing, whether anything's
// gone wrong, then what happens next. "Time since surgery" is derived from
// the date rather than asked separately (see timeSinceSurgery above).
function PostopConditionBlock({ index, condition, poState, onChange, defaultOpen }) {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const set = (key, val) => onChange({ ...poState, [key]: val });

  // "None noted" and any actual complication are mutually exclusive - a
  // note should never be able to say both "no complications" and "wound
  // infection noted" at once.
  const setComplications = (selected) => {
    const prevHadNone = (poState.complications || []).includes("None noted");
    const nowHasNone = selected.includes("None noted");
    if (nowHasNone && !prevHadNone) return set("complications", ["None noted"]);
    if (nowHasNone && selected.length > 1) return set("complications", selected.filter((c) => c !== "None noted"));
    return set("complications", selected);
  };

  const followupSection = condition.sections.find((s) => s.id === "followup");
  const tableField = followupSection && (followupSection.fields || []).find((f) => f.type === "table");
  const intervalOptions = tableField ? [...tableField.rows.map((r) => r.left), "Final", "Other"] : ["Final", "Other"];
  const sinceText = poState.surgeryDate ? timeSinceSurgery(poState.surgeryDate) : null;

  const hasContent =
    !!(poState.procedureName && poState.procedureName.trim()) ||
    !!poState.surgeryDate ||
    (poState.reason || []).length > 0 ||
    (poState.complications || []).length > 0 ||
    (poState.planOptions || []).length > 0 ||
    !!poState.followUpInterval ||
    (poState.nextReviewReason || []).length > 0;

  return (
    <CollapsibleSection index={index} title={condition.name} subtitle="Procedure, current status, complications, plan" isOpen={isOpen} onToggle={() => setIsOpen((v) => !v)} hasContent={hasContent}>
      <SubLabel>Procedure</SubLabel>
      <TextField label="Procedure performed" value={poState.procedureName} onChange={(v) => set("procedureName", v)} placeholder="e.g. Open rotator cuff repair" />
      <DateField label="Date of surgery" value={poState.surgeryDate} onChange={(v) => set("surgeryDate", v)} />
      {sinceText && <div className="text-[12.5px] mt-1 mb-1" style={{ color: T.inkSoft }}>{sinceText} since surgery</div>}

      <SubLabel>Reason for review</SubLabel>
      <CheckboxGroup options={POSTOP_REASON_OPTIONS} selected={poState.reason || []} onChange={(v) => set("reason", v)} />
      {(poState.reason || []).includes("Other") && (
        <TextField label="Specify reason" value={poState.reasonOther} onChange={(v) => set("reasonOther", v)} />
      )}

      <SubLabel>Current status</SubLabel>
      <div className="mb-1 text-[12px] font-semibold uppercase tracking-wide" style={{ color: T.inkSoft }}>Wound</div>
      <ButtonSelect options={POSTOP_WOUND_OPTIONS} value={poState.woundStatus || null} onChange={(v) => set("woundStatus", v)} columns={3} />
      <div className="mb-1 mt-3 text-[12px] font-semibold uppercase tracking-wide" style={{ color: T.inkSoft }}>Pain (VAS)</div>
      <VASSlider value={poState.vas} onChange={(v) => set("vas", v)} />
      <div className="mb-1 mt-3 text-[12px] font-semibold uppercase tracking-wide" style={{ color: T.inkSoft }}>Functional progress</div>
      <ButtonSelect options={POSTOP_PROGRESS_OPTIONS} value={poState.functionalProgress || null} onChange={(v) => set("functionalProgress", v)} columns={1} />
      <TextField label="Additional notes on current status" value={poState.statusNotes} onChange={(v) => set("statusNotes", v)} placeholder="Optional" />

      <SubLabel>Complications</SubLabel>
      <CheckboxGroup options={POSTOP_COMPLICATION_OPTIONS} selected={poState.complications || []} onChange={setComplications} />
      {(poState.complications || []).includes("Other") && (
        <TextField label="Specify complication" value={poState.complicationsOther} onChange={(v) => set("complicationsOther", v)} />
      )}

      <SubLabel>Follow-up plan</SubLabel>
      <div className="text-[12.5px] mb-3" style={{ color: T.inkSoft }}>A post-operative plan is not the same decision as a first-presentation Management Pathway — select what applies now that surgery has already been done.</div>
      <CheckboxGroup options={POSTOP_PLAN_OPTIONS} selected={poState.planOptions || []} onChange={(v) => set("planOptions", v)} />
      {(poState.planOptions || []).includes("Other") && (
        <TextField label="Specify plan" value={poState.planOptionsOther} onChange={(v) => set("planOptionsOther", v)} />
      )}
      {(poState.planOptions || []).includes("Trial of injection") && (
        <InjectionPrompt detail={poState.injectionDetail} onChange={(d) => set("injectionDetail", d)} />
      )}

      <SubLabel>Next review</SubLabel>
      <ButtonSelect options={intervalOptions} value={poState.followUpInterval || null} onChange={(v) => set("followUpInterval", v)} columns={2} />
      {poState.followUpInterval === "Other" && (
        <TextField label="Specify follow-up timing" value={poState.followUpIntervalOther} onChange={(v) => set("followUpIntervalOther", v)} />
      )}
      {poState.followUpInterval && poState.followUpInterval !== "Final" && (
        <>
          <div className="mb-1 mt-3 text-[12px] font-semibold uppercase tracking-wide" style={{ color: T.inkSoft }}>Reason for follow-up</div>
          <CheckboxGroup options={POSTOP_NEXT_REVIEW_REASON_OPTIONS} selected={poState.nextReviewReason || []} onChange={(v) => set("nextReviewReason", v)} />
          {(poState.nextReviewReason || []).includes("Other") && (
            <TextField label="Specify reason for follow-up" value={poState.nextReviewReasonOther} onChange={(v) => set("nextReviewReasonOther", v)} />
          )}
        </>
      )}
    </CollapsibleSection>
  );
}

// Root screen for the Post-operative Follow-up flow - structurally the same
// shell as FollowupVisitScreen (one block per selected procedure/diagnosis
// plus a note preview), reusing that same UX intentionally so the two
// follow-up-style flows feel consistent to a clinician switching between
// them.
function PostopVisitScreen({ conditionIds, session, onFieldChange, onBack, onGoHome }) {
  const [noteOpen, setNoteOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState(false);

  const conditions = conditionIds.map((id) => findConditionById(id)).filter(Boolean);
  const note = useMemo(() => buildCombinedPostopNote(session, conditionIds), [session, conditionIds]);

  const copyNote = async () => {
    const ok = await copyTextRobust(note);
    if (ok) {
      setCopied(true);
      setCopyError(false);
      setTimeout(() => setCopied(false), 1800);
    } else {
      setCopied(false);
      setCopyError(true);
      setTimeout(() => setCopyError(false), 4000);
    }
  };

  return (
    <div className="min-h-screen pb-28" style={{ background: T.bg }}>
      <div className="px-4 pt-5 pb-2 max-w-2xl mx-auto">
        <button onClick={onBack} className="flex items-center gap-1.5 text-[13.5px] font-semibold mb-3 active:opacity-60" style={{ color: T.teal }}>
          <ArrowLeft size={16} /> Change diagnoses
        </button>
        <div className="text-[12px] font-semibold uppercase tracking-widest mb-1" style={{ color: T.teal }}>Post-operative Follow-up</div>
        <h1 className="text-[20px] font-bold mb-4" style={{ color: T.ink }}>{conditions.length} procedure{conditions.length === 1 ? "" : "s"} being reviewed</h1>
      </div>
      <div className="px-4 max-w-2xl mx-auto">
        {conditions.map((condition, i) => {
          const state = session.statesByConditionId[condition.id] || {};
          const poState = state.postop || {};
          return (
            <PostopConditionBlock
              key={condition.id}
              index={i + 1}
              condition={condition}
              poState={poState}
              onChange={(next) => onFieldChange(condition.id, { postop: next })}
              defaultOpen={i === 0}
            />
          );
        })}
      </div>

      <div className="fixed bottom-0 left-0 right-0 z-30 px-3 py-3" style={{ background: T.surface, borderTop: `1px solid ${T.border}` }}>
        <div className="max-w-2xl mx-auto flex gap-2">
          <button onClick={onGoHome} className="rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
            Home
          </button>
          <button onClick={() => setNoteOpen(true)} className="flex-1 rounded-xl px-4 py-3 font-semibold text-[15px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
            Preview post-op note
          </button>
        </div>
      </div>

      {noteOpen && (
        <div className="fixed inset-0 z-40 flex items-end sm:items-center justify-center" style={{ background: "rgba(16,30,43,0.5)" }} onClick={() => setNoteOpen(false)}>
          <div className="w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl" style={{ background: T.surface, display: "flex", flexDirection: "column", maxHeight: "88vh", boxShadow: "0 -4px 24px rgba(16,30,43,0.12)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center gap-1 -ml-1 p-1 active:opacity-60" aria-label="Back to editing">
                <ArrowLeft size={20} color={T.ink} />
              </button>
              <span className="font-bold text-[15px] flex-1" style={{ color: T.ink }}>Post-op follow-up note</span>
            </div>
            <div className="px-4 py-3" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
              <pre className="whitespace-pre-wrap text-[13px] leading-relaxed" style={{ color: T.ink, fontFamily: "ui-monospace, monospace", overflow: "visible", margin: 0 }}>{note}</pre>
            </div>
            <div className="px-4 py-3 flex flex-col gap-2" style={{ borderTop: `1px solid ${T.border}` }}>
              <button onClick={() => setNoteOpen(false)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
                <ArrowLeft size={17} /> Back to editing
              </button>
              <button onClick={copyNote} className="flex items-center justify-center gap-2 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
                {copied ? <Check size={17} /> : <Copy size={17} />}
                {copied ? "Copied" : "Copy to clipboard"}
              </button>
              {copyError && (
                <div className="text-[12.5px] text-center" style={{ color: T.red }}>
                  Couldn't copy automatically \u2014 tap and hold the note above to select and copy it manually.
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* Persistent strip shown above every screen once a patient session has one
   or more active conditions: quick-switch tabs, one-tap access to the
   combined note across all active diagnoses, and ending the session. */
function SessionBar({ session, activeConditionId, onSwitch, onViewCombinedNote, onEndSession, onOpenSearch, onGoHome }) {
  const [confirmEnd, setConfirmEnd] = useState(false);
  const items = session.order.map((id) => findConditionById(id)).filter(Boolean);
  return (
    <div className="sticky top-0 z-40 flex items-center gap-2 px-3 py-2 overflow-x-auto" style={{ background: T.tealDark, boxShadow: "0 1px 3px rgba(16,30,43,0.15)" }}>
      <button onClick={onGoHome} className="shrink-0 flex items-center justify-center rounded-full p-2 active:scale-95 transition" style={{ background: "rgba(255,255,255,0.16)" }} aria-label="Go to home">
        <Home size={16} color="#fff" />
      </button>
      <button onClick={onOpenSearch} className="shrink-0 flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[12.5px] font-semibold active:scale-95 transition" style={{ background: "rgba(255,255,255,0.16)", color: "#fff" }} aria-label="Search templates">
        <Search size={14} color="#fff" />
        <span>Search</span>
      </button>
      {items.length > 0 && (
        <>
          <span className="text-[10.5px] font-semibold uppercase tracking-wide shrink-0" style={{ color: "rgba(255,255,255,0.75)" }}>Session</span>
          {items.map((c) => {
            const active = c.id === activeConditionId;
            return (
              <button
                key={c.id}
                onClick={() => onSwitch(c)}
                className="shrink-0 rounded-full px-3 py-1.5 text-[12.5px] font-medium active:scale-95 transition"
                style={{ background: active ? "#fff" : "rgba(255,255,255,0.16)", color: active ? T.tealDark : "#fff" }}
              >
                {c.name.length > 24 ? c.name.slice(0, 22) + "\u2026" : c.name}
              </button>
            );
          })}
          <button onClick={onViewCombinedNote} className="shrink-0 ml-1 rounded-full px-3 py-1.5 text-[12.5px] font-semibold active:scale-95 transition" style={{ background: "#fff", color: T.tealDark }}>
            Combined note
          </button>
          <button onClick={() => setConfirmEnd(true)} className="shrink-0 rounded-full p-1.5 active:scale-95 transition" style={{ background: "rgba(255,255,255,0.16)" }} aria-label="End session">
            <X size={14} color="#fff" />
          </button>
        </>
      )}

      {confirmEnd && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-6" style={{ background: "rgba(16,30,43,0.5)" }}>
          <div className="w-full max-w-sm rounded-2xl p-5" style={{ background: T.surface, boxShadow: "0 8px 32px rgba(16,30,43,0.18)" }}>
            <div className="font-bold text-[15px] mb-1.5" style={{ color: T.ink }}>End patient session?</div>
            <div className="text-[13.5px] mb-4" style={{ color: T.inkSoft }}>This clears every active condition and all entries for this session. It cannot be undone.</div>
            <div className="flex gap-2">
              <button onClick={() => setConfirmEnd(false)} className="flex-1 rounded-xl px-4 py-2.5 font-semibold text-[14px]" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}` }}>Cancel</button>
              <button
                onClick={() => {
                  onEndSession();
                  setConfirmEnd(false);
                }}
                className="flex-1 rounded-xl px-4 py-2.5 font-semibold text-[14px]"
                style={{ background: T.red, color: "#fff" }}
              >
                End session
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* Full-screen template search, reachable from anywhere via the top bar.
   Searches every condition across every region/subsection by name, and jumps
   straight into the template (adding it to the session) on selection. */
function TemplateSearch({ onSelect, onClose }) {
  const [query, setQuery] = useState("");

  // Grouped by region (Hand further by subsection), in REGIONS' own natural
  // order, so results read as "Shoulder" header then its conditions, then
  // "Elbow" and so on \u2014 rather than a flat list with an inline region tag
  // per row. A group is only shown if it has at least one matching result.
  const groupedResults = useMemo(() => {
    const q = query.trim().toLowerCase();
    const groups = [];
    for (const region of Object.values(REGIONS)) {
      if (region.subsections) {
        for (const sub of region.subsections) {
          const items = sub.conditions.filter((c) => !q || c.name.toLowerCase().includes(q));
          if (items.length) groups.push({ header: `${region.label} \u2014 ${sub.label}`, items });
        }
      } else {
        const items = region.conditions.filter((c) => !q || c.name.toLowerCase().includes(q));
        if (items.length) groups.push({ header: region.label, items });
      }
    }
    return groups;
  }, [query]);

  return (
    <div className="fixed inset-0 z-50 flex flex-col" style={{ background: T.bg }}>
      <div className="flex items-center gap-2 px-3 py-3 sticky top-0" style={{ background: T.surface, borderBottom: `1px solid ${T.border}` }}>
        <button onClick={onClose} className="p-2 -ml-1 active:opacity-60"><ArrowLeft size={22} color={T.ink} /></button>
        <div className="flex-1 flex items-center gap-2 rounded-xl px-3" style={{ background: T.slateChip, border: `1px solid ${T.border}`, minHeight: 44 }}>
          <Search size={17} color={T.inkSoft} />
          <input
            autoFocus
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search templates by name…"
            className="flex-1 bg-transparent py-2.5 text-[15px] outline-none"
            style={{ color: T.ink }}
          />
          {query && (
            <button onClick={() => setQuery("")} className="p-1 active:opacity-60"><X size={16} color={T.inkSoft} /></button>
          )}
        </div>
      </div>
      <div className="px-3 pt-3 pb-8" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
        <div className="max-w-2xl mx-auto">
          {groupedResults.length === 0 ? (
            <div className="rounded-2xl p-6 text-center mt-4" style={{ background: T.surface, border: `1px dashed ${T.borderStrong}` }}>
              <div className="text-[14px] font-medium" style={{ color: T.ink }}>No templates match "{query}"</div>
            </div>
          ) : (
            <div className="flex flex-col gap-5">
              {groupedResults.map((group) => (
                <div key={group.header}>
                  <div className="text-[12px] font-bold uppercase tracking-wide mb-2 px-1" style={{ color: T.teal }}>{group.header}</div>
                  <div className="flex flex-col gap-2.5">
                    {group.items.map((condition) => (
                      <button
                        key={condition.id}
                        onClick={() => onSelect(condition)}
                        className="rounded-2xl px-4 py-3.5 text-left active:scale-95 transition"
                        style={{ background: T.surface, border: `1px solid ${T.border}`, minHeight: 52 }}
                      >
                        <span className="font-semibold text-[15px]" style={{ color: T.ink }}>{condition.name}</span>
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// Lets the clinician pick one or more existing diagnoses to follow up on in
// this visit, reusing the same flat searchable listing as TemplateSearch but
// with multi-select (tap to toggle) instead of navigate-on-tap, since a
// follow-up visit commonly covers more than one coexisting diagnosis.
function FollowupConditionPicker({ selectedIds, onToggle, onContinue, onBack }) {
  const [query, setQuery] = useState("");

  // Grouped by region (Hand further by subsection), in REGIONS' own natural
  // order - same grouping approach as TemplateSearch, and shared by both the
  // Follow-up Visit and Post-operative Follow-up flows since they both use
  // this picker.
  const groupedResults = useMemo(() => {
    const q = query.trim().toLowerCase();
    const groups = [];
    for (const region of Object.values(REGIONS)) {
      if (region.subsections) {
        for (const sub of region.subsections) {
          const items = sub.conditions.filter((c) => !q || c.name.toLowerCase().includes(q));
          if (items.length) groups.push({ header: `${region.label} \u2014 ${sub.label}`, items });
        }
      } else {
        const items = region.conditions.filter((c) => !q || c.name.toLowerCase().includes(q));
        if (items.length) groups.push({ header: region.label, items });
      }
    }
    return groups;
  }, [query]);

  return (
    <div className="fixed inset-0 z-30 flex flex-col" style={{ background: T.bg }}>
      <div className="flex items-center gap-2 px-3 py-3 sticky top-0" style={{ background: T.surface, borderBottom: `1px solid ${T.border}` }}>
        <button onClick={onBack} className="p-2 -ml-1 active:opacity-60"><ArrowLeft size={22} color={T.ink} /></button>
        <div className="flex-1">
          <div className="font-bold text-[15px]" style={{ color: T.ink }}>Follow-up Visit</div>
          <div className="text-[12px]" style={{ color: T.inkSoft }}>Select the diagnosis (or diagnoses) being reviewed</div>
        </div>
      </div>
      <div className="px-3 pt-3">
        <div className="max-w-2xl mx-auto flex items-center gap-2 rounded-xl px-3" style={{ background: T.slateChip, border: `1px solid ${T.border}`, minHeight: 44 }}>
          <Search size={17} color={T.inkSoft} />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search diagnoses…"
            className="flex-1 bg-transparent py-2.5 text-[15px] outline-none"
            style={{ color: T.ink }}
          />
          {query && (
            <button onClick={() => setQuery("")} className="p-1 active:opacity-60"><X size={16} color={T.inkSoft} /></button>
          )}
        </div>
      </div>
      <div className="px-3 pt-3 pb-28" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
        <div className="max-w-2xl mx-auto">
          {groupedResults.length === 0 ? (
            <div className="rounded-2xl p-6 text-center mt-4" style={{ background: T.surface, border: `1px dashed ${T.borderStrong}` }}>
              <div className="text-[14px] font-medium" style={{ color: T.ink }}>No diagnoses match "{query}"</div>
            </div>
          ) : (
            <div className="flex flex-col gap-5">
              {groupedResults.map((group) => (
                <div key={group.header}>
                  <div className="text-[12px] font-bold uppercase tracking-wide mb-2 px-1" style={{ color: T.teal }}>{group.header}</div>
                  <div className="flex flex-col gap-2.5">
                    {group.items.map((condition) => {
                      const active = selectedIds.includes(condition.id);
                      return (
                        <button
                          key={condition.id}
                          onClick={() => onToggle(condition.id)}
                          className="rounded-2xl px-4 py-3.5 flex items-center justify-between text-left active:scale-95 transition"
                          style={{ background: active ? T.tealTint : T.surface, border: `1px solid ${active ? T.teal : T.border}`, minHeight: 52 }}
                        >
                          <span className="font-semibold text-[15px]" style={{ color: active ? T.tealDark : T.ink }}>{condition.name}</span>
                          {active ? <CheckCircle2 size={20} color={T.teal} /> : <Circle size={20} color={T.borderStrong} />}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
      <div className="fixed bottom-0 left-0 right-0 px-3 py-3" style={{ background: T.surface, borderTop: `1px solid ${T.border}` }}>
        <div className="max-w-2xl mx-auto">
          <button
            onClick={onContinue}
            disabled={!selectedIds.length}
            className="w-full rounded-xl px-4 py-3.5 font-semibold text-[15px] active:scale-95 transition"
            style={{ background: selectedIds.length ? T.teal : T.slateChip, color: selectedIds.length ? "#fff" : T.inkSoft, minHeight: 50 }}
          >
            {selectedIds.length ? `Continue with ${selectedIds.length} diagnos${selectedIds.length === 1 ? "is" : "es"}` : "Select at least one diagnosis"}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================================
   ROOT APP
============================================================================ */
export default function App() {
  const [screen, setScreen] = useState({ view: "visitType" });
  const [session, setSession] = useState({ order: [], statesByConditionId: {} });
  const [combinedNoteOpen, setCombinedNoteOpen] = useState(false);
  const [combinedCopied, setCombinedCopied] = useState(false);
  const [combinedCopyError, setCombinedCopyError] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);

  const openCondition = useCallback((condition) => {
    setSession((s) => addConditionToSession(s, condition));
    setScreen({ view: "template", regionKey: condition.region, condition });
  }, []);

  const selectFromSearch = useCallback(
    (condition) => {
      openCondition(condition);
      setSearchOpen(false);
    },
    [openCondition]
  );

  const updateConditionState = useCallback((conditionId, patch) => {
    setSession((s) => ({
      ...s,
      statesByConditionId: {
        ...s.statesByConditionId,
        [conditionId]: { ...(s.statesByConditionId[conditionId] || {}), ...patch },
      },
    }));
  }, []);

  const resetCondition = useCallback((conditionId) => {
    setSession((s) => ({ ...s, statesByConditionId: { ...s.statesByConditionId, [conditionId]: {} } }));
  }, []);

  const endSession = useCallback(() => {
    setSession({ order: [], statesByConditionId: {} });
    setCombinedNoteOpen(false);
    setScreen({ view: "visitType" });
  }, []);

  // Follow-up Visit and Post-operative Follow-up share the same diagnosis
  // picker (FollowupConditionPicker) and selection state; only where
  // "Continue" routes to afterward differs. Selected diagnoses are added to
  // the session (same infrastructure as New Visit, so all three flows can
  // coexist and share one combined note).
  const [followupSelectedIds, setFollowupSelectedIds] = useState([]);
  const toggleFollowupSelection = useCallback((conditionId) => {
    setFollowupSelectedIds((ids) => (ids.includes(conditionId) ? ids.filter((id) => id !== conditionId) : [...ids, conditionId]));
  }, []);
  const addSelectedToSession = useCallback(() => {
    followupSelectedIds.forEach((id) => {
      const condition = findConditionById(id);
      if (condition) setSession((s) => addConditionToSession(s, condition));
    });
  }, [followupSelectedIds]);
  const continueToFollowupVisit = useCallback(() => {
    addSelectedToSession();
    setScreen({ view: "followupVisit", conditionIds: followupSelectedIds });
  }, [followupSelectedIds, addSelectedToSession]);
  const continueToPostopVisit = useCallback(() => {
    addSelectedToSession();
    setScreen({ view: "postopVisit", conditionIds: followupSelectedIds });
  }, [followupSelectedIds, addSelectedToSession]);

  const goHome = useCallback(() => {
    setScreen({ view: "visitType" });
    setFollowupSelectedIds([]);
  }, []);

  const combinedNote = useMemo(() => buildCombinedNote(session), [session]);
  const copyCombinedNote = async () => {
    const ok = await copyTextRobust(combinedNote);
    if (ok) {
      setCombinedCopied(true);
      setCombinedCopyError(false);
      setTimeout(() => setCombinedCopied(false), 1800);
    } else {
      setCombinedCopied(false);
      setCombinedCopyError(true);
      setTimeout(() => setCombinedCopyError(false), 4000);
    }
  };

  return (
    <div>
      <SessionBar
        session={session}
        activeConditionId={screen.view === "template" ? screen.condition.id : null}
        onSwitch={openCondition}
        onViewCombinedNote={() => setCombinedNoteOpen(true)}
        onEndSession={endSession}
        onOpenSearch={() => setSearchOpen(true)}
        onGoHome={goHome}
      />

      {screen.view === "visitType" && (
        <VisitTypeGate
          onSelect={(type) => {
            if (type === "new") setScreen({ view: "regions" });
            else {
              setFollowupSelectedIds([]);
              setScreen({ view: type === "postop" ? "postopSelect" : "followupSelect" });
            }
          }}
        />
      )}

      {screen.view === "followupSelect" && (
        <FollowupConditionPicker
          selectedIds={followupSelectedIds}
          onToggle={toggleFollowupSelection}
          onContinue={continueToFollowupVisit}
          onBack={goHome}
        />
      )}

      {screen.view === "postopSelect" && (
        <FollowupConditionPicker
          selectedIds={followupSelectedIds}
          onToggle={toggleFollowupSelection}
          onContinue={continueToPostopVisit}
          onBack={goHome}
        />
      )}

      {screen.view === "followupVisit" && (
        <FollowupVisitScreen
          conditionIds={screen.conditionIds}
          session={session}
          onFieldChange={updateConditionState}
          onBack={() => setScreen({ view: "followupSelect" })}
          onGoHome={goHome}
        />
      )}

      {screen.view === "postopVisit" && (
        <PostopVisitScreen
          conditionIds={screen.conditionIds}
          session={session}
          onFieldChange={updateConditionState}
          onBack={() => setScreen({ view: "postopSelect" })}
          onGoHome={goHome}
        />
      )}

      {screen.view === "regions" && <RegionPicker onSelect={(regionKey) => setScreen({ view: "conditions", regionKey })} onBack={goHome} />}

      {screen.view === "conditions" && (
        <ConditionList
          regionKey={screen.regionKey}
          session={session}
          onSelect={openCondition}
          onBack={() => setScreen({ view: "regions" })}
        />
      )}

      {screen.view === "template" && (
        <ConditionTemplate
          condition={screen.condition}
          state={session.statesByConditionId[screen.condition.id] || {}}
          onFieldChange={(patch) => updateConditionState(screen.condition.id, patch)}
          session={session}
          onOpenCondition={openCondition}
          onResetCondition={() => resetCondition(screen.condition.id)}
          onBack={() => setScreen({ view: "conditions", regionKey: screen.regionKey })}
        />
      )}

      {combinedNoteOpen && (
        <div className="fixed inset-0 z-40 flex items-end sm:items-center justify-center" style={{ background: "rgba(16,30,43,0.5)" }} onClick={() => setCombinedNoteOpen(false)}>
          <div className="w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl" style={{ background: T.surface, display: "flex", flexDirection: "column", maxHeight: "88vh", boxShadow: "0 -4px 24px rgba(16,30,43,0.12)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-2 px-4 py-3" style={{ borderBottom: `1px solid ${T.border}` }}>
              <button onClick={() => setCombinedNoteOpen(false)} className="flex items-center gap-1 -ml-1 p-1 active:opacity-60" aria-label="Back to editing">
                <ArrowLeft size={20} color={T.ink} />
              </button>
              <span className="font-bold text-[15px] flex-1" style={{ color: T.ink }}>Combined clinic note</span>
            </div>
            <div className="px-4 py-3" style={{ flex: "1 1 0%", minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
              <pre className="whitespace-pre-wrap text-[13px] leading-relaxed" style={{ color: T.ink, fontFamily: "ui-monospace, monospace", overflow: "visible", margin: 0 }}>{combinedNote}</pre>
            </div>
            <div className="px-4 py-3 flex flex-col gap-2" style={{ borderTop: `1px solid ${T.border}` }}>
              <button onClick={() => setCombinedNoteOpen(false)} className="flex items-center justify-center gap-1.5 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.slateChip, color: T.ink, border: `1px solid ${T.border}`, minHeight: 48 }}>
                <ArrowLeft size={17} /> Back to editing
              </button>
              <button onClick={copyCombinedNote} className="flex items-center justify-center gap-2 rounded-xl px-4 py-3 font-semibold text-[14px] active:scale-95" style={{ background: T.teal, color: "#fff", minHeight: 48 }}>
                {combinedCopied ? <Check size={17} /> : <Copy size={17} />}
                {combinedCopied ? "Copied" : "Copy to clipboard"}
              </button>
              {combinedCopyError && (
                <div className="text-[12.5px] text-center mt-2" style={{ color: T.red }}>
                  Couldn't copy automatically \u2014 tap and hold the note above to select and copy it manually.
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {searchOpen && <TemplateSearch onSelect={selectFromSearch} onClose={() => setSearchOpen(false)} />}
    </div>
  );
}
